export const financialManagementTextbookHtml = "\n  <div class=\"tkd-page-scope font-sans antialiased bg-[#FAF8F6] text-[#333333]\">\n\n    <!-- COVER HEADER CHO BẢN IN HOẶC XUẤT PDF A4 -->\n    <div class=\"print-document-header hidden print:block text-center border-b-2 border-[#8B1E2D] pb-4 mb-6\">\n      <div class=\"text-[12pt] font-semibold text-[#8B1E2D] tracking-wider uppercase\">TRƯỜNG CAO ĐẲNG KINH TẾ TP. HỒ CHÍ MINH — KHOA QUẢN TRỊ KINH DOANH</div>\n      <h1 class=\"text-[20pt] font-extrabold text-[#111827] uppercase tracking-tight mt-2 mb-1\">\n        GIÁO TRÌNH QUẢN TRỊ TÀI CHÍNH (MH21)\n      </h1>\n      <div class=\"text-[11pt] text-[#4B5563] italic\">\n        Tài liệu học tập chính quy bậc Cao đẳng &amp; Đại học — Chủ biên: ThS. NGUYỄN THỊ TRÚC PHƯƠNG\n      </div>\n      <div class=\"text-[10pt] text-[#6B7280] mt-2 flex justify-between items-center border-t border-[#E5E7EB] pt-1\">\n        <span>Mã học phần: MH21 (3 tín chỉ / 45 tiết)</span>\n        <span class=\"print-timestamp\">Năm học: <span class=\"js-current-year\"></span></span>\n        <span>Cổng học liệu số: NGUYỄN THỊ TRÚC PHƯƠNG</span>\n      </div>\n    </div>\n\n    <!-- HEADER BANNER ONLINE LUXURY RED TONE -->\n    <header class=\"no-print w-full bg-gradient-to-r from-[#8B1E2D] via-[#A32234] to-[#C62828] text-white py-8 sm:py-10 px-4 shadow-md border-b border-[#FCEEEF]/20\">\n      <div class=\"max-w-5xl mx-auto text-center space-y-2\">\n        <div class=\"inline-flex items-center gap-2 px-3 py-1 rounded-full bg-white/15 backdrop-blur-sm border border-white/25 text-xs font-semibold tracking-wider uppercase text-[#FCEEEF]\">\n          <span>📘</span> Giáo Trình Học Phần Trọng Tâm — Bậc Cao Đẳng &amp; Đại Học\n        </div>\n        <h1 class=\"text-xl sm:text-2xl md:text-3xl lg:text-4xl font-extrabold tracking-tight uppercase leading-tight text-white drop-shadow-xs m-0\">\n          GIÁO TRÌNH QUẢN TRỊ TÀI CHÍNH\n        </h1>\n        <p class=\"text-xs sm:text-sm text-[#FCEEEF]/90 max-w-3xl mx-auto font-medium leading-relaxed\">\n          Chủ biên: <strong>ThS. Nguyễn Thị Trúc Phương</strong> — Khoa Quản trị Kinh doanh, Trường Cao đẳng Kinh tế TP.HCM (HCE). Hệ thống 8 chương chuẩn hóa học thuật: từ báo cáo tài chính, mô hình DuPont, đòn bẩy kinh doanh/tài chính, quản trị vốn lưu động, chiết khấu dòng tiền, chi phí vốn WACC đến cơ cấu vốn tối ưu.\n        </p>\n      </div>\n    </header>\n\n    <!-- THANH ĐIỀU HƯỚNG NHANH & HÀNH ĐỘNG HỌC LIỆU -->\n    <div class=\"no-print bg-white border-b border-[#E8E0E1] sticky top-0 z-30 shadow-2xs\">\n      <div class=\"max-w-5xl mx-auto px-3.5 sm:px-6 py-2.5 flex flex-wrap items-center justify-between gap-2 text-xs\">\n        <div class=\"flex items-center gap-2\">\n          <a href=\"/study-corner\" class=\"inline-flex items-center gap-1.5 font-bold text-[#8B1E2D] hover:text-[#C62828] bg-[#FCEEEF] px-3 py-1.5 rounded-lg transition-colors\">\n            <span>←</span> Về Góc Học Tập\n          </a>\n          <a href=\"/study-corner/financial-management/intro\" class=\"inline-flex items-center gap-1.5 font-bold text-slate-700 hover:text-[#8B1E2D] bg-slate-100 px-3 py-1.5 rounded-lg transition-colors\">\n            <span>📋</span> Giới Thiệu &amp; Đề Cương\n          </a>\n        </div>\n        <div class=\"flex items-center gap-2\">\n          <button type=\"button\" onclick=\"window.print()\" class=\"inline-flex items-center gap-1.5 font-bold text-[#8B1E2D] hover:bg-[#FCEEEF] border border-[#8B1E2D]/40 px-3 py-1.5 rounded-lg transition-all cursor-pointer\">\n            <span>🖨️</span> In Giáo Trình\n          </button>\n          <button type=\"button\" onclick=\"window.print()\" class=\"inline-flex items-center gap-1.5 font-bold text-white bg-[#8B1E2D] hover:bg-[#C62828] px-3 py-1.5 rounded-lg transition-all shadow-2xs cursor-pointer\">\n            <span>📄</span> Xuất PDF A4\n          </button>\n        </div>\n      </div>\n    </div>\n\n    <!-- KHUNG THÔNG TIN HỌC PHẦN TỔNG QUAN -->\n    <div class=\"max-w-5xl mx-auto px-3.5 sm:px-6 pt-6\">\n      <div class=\"bg-white rounded-2xl border border-[#E8E0E1] p-4 sm:p-6 shadow-2xs grid grid-cols-2 sm:grid-cols-4 gap-4 text-center\">\n        <div class=\"border-r border-[#E8E0E1] last:border-r-0\">\n          <span class=\"block text-2xs font-bold text-slate-500 uppercase tracking-wider\">Mã Học Phần</span>\n          <span class=\"text-sm sm:text-base font-extrabold text-[#8B1E2D]\">MH21</span>\n        </div>\n        <div class=\"border-r border-[#E8E0E1] last:border-r-0\">\n          <span class=\"block text-2xs font-bold text-slate-500 uppercase tracking-wider\">Khối Lượng</span>\n          <span class=\"text-sm sm:text-base font-extrabold text-slate-900\">3 Tín Chỉ (45 Tiết)</span>\n        </div>\n        <div class=\"border-r border-[#E8E0E1] last:border-r-0\">\n          <span class=\"block text-2xs font-bold text-slate-500 uppercase tracking-wider\">Chủ Biên</span>\n          <span class=\"text-sm sm:text-base font-extrabold text-[#8B1E2D]\">ThS. Nguyễn Thị Trúc Phương</span>\n        </div>\n        <div>\n          <span class=\"block text-2xs font-bold text-slate-500 uppercase tracking-wider\">Đơn Vị Quản Lý</span>\n          <span class=\"text-sm sm:text-base font-extrabold text-slate-900\">Khoa QTKD — HCE</span>\n        </div>\n      </div>\n    </div>\n\n    <!-- THÂN TRANG CHẠY DÀI TỰ NHIÊN (MAX-W-5XL) -->\n    <div class=\"max-w-5xl mx-auto px-3.5 sm:px-6 py-6 space-y-8\">\n\n      <!-- MỤC LỤC TỔNG THỂ GIÁO TRÌNH -->\n      <nav aria-label=\"Mục lục giáo trình\" class=\"no-print rounded-3xl bg-white border border-[#E8E0E1] p-5 sm:p-8 shadow-sm\">\n        <div class=\"flex items-center justify-between gap-2 mb-4\">\n          <div class=\"flex items-center gap-2\">\n            <span class=\"px-3 py-1 rounded-full bg-[#FCEEEF] text-[#8B1E2D] text-xs font-bold tracking-wider uppercase\">Cấu Trúc Giáo Trình Chuẩn Hóa</span>\n          </div>\n          <span class=\"text-xs font-semibold text-slate-500\">8 Chương Hoàn Chỉnh</span>\n        </div>\n        <h2 class=\"text-xl sm:text-2xl font-extrabold text-[#111827] tracking-tight mb-4\">\n          MỤC LỤC TỔNG THỂ GIÁO TRÌNH QUẢN TRỊ TÀI CHÍNH\n        </h2>\n        <div class=\"grid grid-cols-1 sm:grid-cols-2 md:grid-cols-4 gap-3\">\n          <a href=\"#chuong-1\" class=\"block p-3.5 rounded-2xl bg-[#FAF8F6] border border-[#E8E0E1] hover:border-[#8B1E2D] hover:bg-[#FCEEEF]/40 transition-all group no-underline text-[#333333]\">\n            <div class=\"flex items-start gap-3\">\n              <span class=\"w-8 h-8 rounded-xl bg-[#8B1E2D] text-white font-black text-xs flex items-center justify-center shrink-0 group-hover:bg-[#C62828] transition-colors shadow-2xs\">01</span>\n              <div>\n                <h3 class=\"font-bold text-[#111827] text-xs sm:text-sm group-hover:text-[#8B1E2D] mb-1\">Tổng quan quản trị tài chính</h3>\n                <p class=\"text-2xs text-[#666666] line-clamp-2\">Bản chất, 3 nhóm quyết định, mục tiêu tối đa hóa giá trị &amp; vai trò CFO.</p>\n              </div>\n            </div>\n          </a>\n          <a href=\"#chuong-2\" class=\"block p-3.5 rounded-2xl bg-[#FAF8F6] border border-[#E8E0E1] hover:border-[#8B1E2D] hover:bg-[#FCEEEF]/40 transition-all group no-underline text-[#333333]\">\n            <div class=\"flex items-start gap-3\">\n              <span class=\"w-8 h-8 rounded-xl bg-[#8B1E2D] text-white font-black text-xs flex items-center justify-center shrink-0 group-hover:bg-[#C62828] transition-colors shadow-2xs\">02</span>\n              <div>\n                <h3 class=\"font-bold text-[#111827] text-xs sm:text-sm group-hover:text-[#8B1E2D] mb-1\">Phân tích tài chính</h3>\n                <p class=\"text-2xs text-[#666666] line-clamp-2\">Hệ thống báo cáo tài chính, 4 nhóm tỷ số then chốt &amp; mô hình DuPont.</p>\n              </div>\n            </div>\n          </a>\n          <a href=\"#chuong-3\" class=\"block p-3.5 rounded-2xl bg-[#FAF8F6] border border-[#E8E0E1] hover:border-[#8B1E2D] hover:bg-[#FCEEEF]/40 transition-all group no-underline text-[#333333]\">\n            <div class=\"flex items-start gap-3\">\n              <span class=\"w-8 h-8 rounded-xl bg-[#8B1E2D] text-white font-black text-xs flex items-center justify-center shrink-0 group-hover:bg-[#C62828] transition-colors shadow-2xs\">03</span>\n              <div>\n                <h3 class=\"font-bold text-[#111827] text-xs sm:text-sm group-hover:text-[#8B1E2D] mb-1\">Hoạch định lợi nhuận &amp; đòn bẩy</h3>\n                <p class=\"text-2xs text-[#666666] line-clamp-2\">Phân loại chi phí, điểm hòa vốn BEP, đòn bẩy kinh doanh DOL &amp; tài chính DFL.</p>\n              </div>\n            </div>\n          </a>\n          <a href=\"#chuong-4\" class=\"block p-3.5 rounded-2xl bg-[#FAF8F6] border border-[#E8E0E1] hover:border-[#8B1E2D] hover:bg-[#FCEEEF]/40 transition-all group no-underline text-[#333333]\">\n            <div class=\"flex items-start gap-3\">\n              <span class=\"w-8 h-8 rounded-xl bg-[#8B1E2D] text-white font-black text-xs flex items-center justify-center shrink-0 group-hover:bg-[#C62828] transition-colors shadow-2xs\">04</span>\n              <div>\n                <h3 class=\"font-bold text-[#111827] text-xs sm:text-sm group-hover:text-[#8B1E2D] mb-1\">Quản trị vốn lưu động</h3>\n                <p class=\"text-2xs text-[#666666] line-clamp-2\">Vốn lưu động ròng NWC, quản trị tiền Baumol, khoản phải thu &amp; tồn kho EOQ.</p>\n              </div>\n            </div>\n          </a>\n          <a href=\"#chuong-5\" class=\"block p-3.5 rounded-2xl bg-[#FAF8F6] border border-[#E8E0E1] hover:border-[#8B1E2D] hover:bg-[#FCEEEF]/40 transition-all group no-underline text-[#333333]\">\n            <div class=\"flex items-start gap-3\">\n              <span class=\"w-8 h-8 rounded-xl bg-[#8B1E2D] text-white font-black text-xs flex items-center justify-center shrink-0 group-hover:bg-[#C62828] transition-colors shadow-2xs\">05</span>\n              <div>\n                <h3 class=\"font-bold text-[#111827] text-xs sm:text-sm group-hover:text-[#8B1E2D] mb-1\">Nguồn tài trợ của doanh nghiệp</h3>\n                <p class=\"text-2xs text-[#666666] line-clamp-2\">Nguồn tài trợ ngắn hạn, chi phí tín dụng thương mại &amp; tài trợ dài hạn.</p>\n              </div>\n            </div>\n          </a>\n          <a href=\"#chuong-6\" class=\"block p-3.5 rounded-2xl bg-[#FAF8F6] border border-[#E8E0E1] hover:border-[#8B1E2D] hover:bg-[#FCEEEF]/40 transition-all group no-underline text-[#333333]\">\n            <div class=\"flex items-start gap-3\">\n              <span class=\"w-8 h-8 rounded-xl bg-[#8B1E2D] text-white font-black text-xs flex items-center justify-center shrink-0 group-hover:bg-[#C62828] transition-colors shadow-2xs\">06</span>\n              <div>\n                <h3 class=\"font-bold text-[#111827] text-xs sm:text-sm group-hover:text-[#8B1E2D] mb-1\">Giá trị tiền tệ theo thời gian</h3>\n                <p class=\"text-2xs text-[#666666] line-clamp-2\">Lãi đơn, lãi kép, giá trị tương lai FV, giá trị hiện tại PV, niên kim &amp; dòng tiền.</p>\n              </div>\n            </div>\n          </a>\n          <a href=\"#chuong-7\" class=\"block p-3.5 rounded-2xl bg-[#FAF8F6] border border-[#E8E0E1] hover:border-[#8B1E2D] hover:bg-[#FCEEEF]/40 transition-all group no-underline text-[#333333]\">\n            <div class=\"flex items-start gap-3\">\n              <span class=\"w-8 h-8 rounded-xl bg-[#8B1E2D] text-white font-black text-xs flex items-center justify-center shrink-0 group-hover:bg-[#C62828] transition-colors shadow-2xs\">07</span>\n              <div>\n                <h3 class=\"font-bold text-[#111827] text-xs sm:text-sm group-hover:text-[#8B1E2D] mb-1\">Định giá chứng khoán &amp; WACC</h3>\n                <p class=\"text-2xs text-[#666666] line-clamp-2\">Định giá trái phiếu, mô hình Gordon, CAPM và chi phí vốn bình quân WACC.</p>\n              </div>\n            </div>\n          </a>\n          <a href=\"#chuong-8\" class=\"block p-3.5 rounded-2xl bg-[#FAF8F6] border border-[#E8E0E1] hover:border-[#8B1E2D] hover:bg-[#FCEEEF]/40 transition-all group no-underline text-[#333333]\">\n            <div class=\"flex items-start gap-3\">\n              <span class=\"w-8 h-8 rounded-xl bg-[#8B1E2D] text-white font-black text-xs flex items-center justify-center shrink-0 group-hover:bg-[#C62828] transition-colors shadow-2xs\">08</span>\n              <div>\n                <h3 class=\"font-bold text-[#111827] text-xs sm:text-sm group-hover:text-[#8B1E2D] mb-1\">Cơ cấu vốn &amp; Điểm bàng quan</h3>\n                <p class=\"text-2xs text-[#666666] line-clamp-2\">Cơ cấu vốn tối ưu, lý thuyết MM, đánh đổi Trade-off &amp; phân tích EBIT-EPS.</p>\n              </div>\n            </div>\n          </a>\n        </div>\n      </nav>\n\n      <!-- ========================================================================= -->\n      <!-- CHƯƠNG 1: TỔNG QUAN VỀ QUẢN TRỊ TÀI CHÍNH                                 -->\n      <!-- ========================================================================= -->\n      <section id=\"chuong-1\" class=\"bg-white rounded-xl shadow-sm border border-[#E5E7EB] p-6 sm:p-8 space-y-6\">\n\n          <!-- Chapter Header Banner -->\n          <div class=\"border-b-2 border-[#8B1E2D] pb-3 mb-6\">\n  <span class=\"text-xs font-bold text-[#8B1E2D] uppercase tracking-wider\">Chương 1 (MH21.01)</span>\n  <h2 class=\"text-2xl font-black text-[#111827] mt-1\">TỔNG QUAN VỀ QUẢN TRỊ TÀI CHÍNH DOANH NGHIỆP</h2>\n  <p class=\"text-xs sm:text-sm text-gray-600 mt-1 leading-relaxed\">Bản chất của tài chính doanh nghiệp, các mối quan hệ tài chính, 3 quyết định tài chính then chốt, mục tiêu tối đa hóa giá trị doanh nghiệp, môi trường tài chính và vai trò của Giám đốc Tài chính (CFO).</p>\n</div>\n\n          <!-- Chapter Objectives Card -->\n          <div class=\"bg-gradient-to-br from-white via-[#FCEEEF]/40 to-[#FAF8F6] rounded-2xl border border-[#E8E0E1] p-4 sm:p-5 shadow-2xs\">\n            <div class=\"flex items-center gap-2.5 mb-3 border-b border-[#E8E0E1] pb-2.5\">\n              <span class=\"w-7 h-7 rounded-lg bg-[#8B1E2D] text-white flex items-center justify-center text-sm font-bold\">🎯</span>\n              <div>\n                <h3 class=\"font-extrabold text-[#111827] text-xs sm:text-sm m-0 tracking-tight\">Mục Tiêu Trọng Tâm Chương 1</h3>\n                <p class=\"text-[11px] text-[#666666] m-0\">Sau khi học xong chương này, người học có khả năng:</p>\n              </div>\n            </div>\n            <div class=\"grid grid-cols-1 sm:grid-cols-2 gap-3 text-xs\">\n              <div class=\"p-3 bg-white rounded-xl border border-[#E8E0E1] flex items-start gap-2.5\">\n                <span class=\"w-5 h-5 rounded-md bg-[#8B1E2D] text-white font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">1</span>\n                <div>\n                  <strong class=\"text-[#111827]\">Khái niệm &amp; Bản chất:</strong>\n                  <p class=\"text-[#666666] m-0 mt-0.5\">Trình bày được định nghĩa quản trị tài chính, các dòng luân chuyển vốn và các mối quan hệ kinh tế phát sinh trong hoạt động doanh nghiệp.</p>\n                </div>\n              </div>\n              <div class=\"p-3 bg-white rounded-xl border border-[#E8E0E1] flex items-start gap-2.5\">\n                <span class=\"w-5 h-5 rounded-md bg-[#8B1E2D] text-white font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">2</span>\n                <div>\n                  <strong class=\"text-[#111827]\">3 Quyết định tài chính then chốt:</strong>\n                  <p class=\"text-[#666666] m-0 mt-0.5\">Phân tích rõ quyết định đầu tư (Investment), quyết định tài trợ (Financing) và quyết định quản trị tài sản hoạt động (Asset Management).</p>\n                </div>\n              </div>\n              <div class=\"p-3 bg-white rounded-xl border border-[#E8E0E1] flex items-start gap-2.5\">\n                <span class=\"w-5 h-5 rounded-md bg-[#8B1E2D] text-white font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">3</span>\n                <div>\n                  <strong class=\"text-[#111827]\">Mục tiêu tối thượng:</strong>\n                  <p class=\"text-[#666666] m-0 mt-0.5\">Phân biệt sự khác nhau giữa mục tiêu tối đa hóa lợi nhuận kế toán và mục tiêu tối đa hóa giá trị doanh nghiệp / tài sản của chủ sở hữu.</p>\n                </div>\n              </div>\n              <div class=\"p-3 bg-white rounded-xl border border-[#E8E0E1] flex items-start gap-2.5\">\n                <span class=\"w-5 h-5 rounded-md bg-[#8B1E2D] text-white font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">4</span>\n                <div>\n                  <strong class=\"text-[#111827]\">Môi trường &amp; Tổ chức bộ máy:</strong>\n                  <p class=\"text-[#666666] m-0 mt-0.5\">Mô tả tác động của thị trường tài chính, lãi suất, thuế, lạm phát và cấu trúc bộ phận tài chính dưới sự điều hành của CFO.</p>\n                </div>\n              </div>\n            </div>\n          </div>\n\n          <!-- Section 1.1 -->\n          <div class=\"space-y-3\">\n            <h3 class=\"text-base sm:text-lg font-extrabold text-[#8B1E2D] border-b border-[#E8E0E1] pb-1.5 flex items-center gap-2\">\n              <span>1.1.</span> Khái Niệm Và Bản Chất Của Tài Chính Doanh Nghiệp\n            </h3>\n            <p class=\"text-xs sm:text-sm text-[#333333] leading-relaxed\">\n              <strong>Tài chính doanh nghiệp (Corporate Finance)</strong> là hệ thống các quan hệ kinh tế dưới hình thái tiền tệ phát sinh trong quá trình tạo lập, phân phối và sử dụng các quỹ tiền tệ nhằm phục vụ cho mục đích sản xuất kinh doanh và tạo ra giá trị thặng dư.\n            </p>\n            <div class=\"border-l-4 border-[#8B1E2D] bg-[#FCEEEF]/50 p-4 rounded-r-xl my-3 text-xs sm:text-sm\">\n              <strong class=\"text-[#8B1E2D] font-bold block mb-1\">Khái niệm Quản trị Tài chính (Financial Management):</strong>\n              <p class=\"m-0 leading-relaxed text-[#333333]\">\n                Quản trị tài chính là việc ứng dụng các nguyên lý kinh tế học và tài chính vào việc ra các quyết định liên quan đến việc huy động, phân bổ và kiểm soát các nguồn lực tài chính của doanh nghiệp nhằm đạt được mục tiêu chiến lược tối đa hóa giá trị doanh nghiệp.\n              </p>\n            </div>\n            <p class=\"text-xs sm:text-sm text-[#333333] leading-relaxed\">\n              Các mối quan hệ tài chính cơ bản của doanh nghiệp bao gồm 5 nhóm chính:\n            </p>\n            <div class=\"grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-3 my-3 text-xs\">\n              <div class=\"p-3 bg-[#FAF8F6] rounded-xl border border-[#E8E0E1] space-y-1\">\n                <strong class=\"text-[#8B1E2D]\">1. Doanh nghiệp với Nhà nước:</strong>\n                <p class=\"text-[#666666] m-0 leading-relaxed\">Thực hiện nghĩa vụ nộp thuế (TNDN, GTGT, XNK, TNCN), lệ phí và tiếp nhận các khoản hỗ trợ, ưu đãi đầu tư từ ngân sách.</p>\n              </div>\n              <div class=\"p-3 bg-[#FAF8F6] rounded-xl border border-[#E8E0E1] space-y-1\">\n                <strong class=\"text-[#8B1E2D]\">2. Doanh nghiệp với Thị trường tài chính:</strong>\n                <p class=\"text-[#666666] m-0 leading-relaxed\">Vay vốn ngân hàng thương mại, phát hành trái phiếu, phát hành cổ phiếu, gửi tiền và đầu tư các công cụ tài chính sinh lời.</p>\n              </div>\n              <div class=\"p-3 bg-[#FAF8F6] rounded-xl border border-[#E8E0E1] space-y-1\">\n                <strong class=\"text-[#8B1E2D]\">3. Doanh nghiệp với Khách hàng &amp; Nhà cung cấp:</strong>\n                <p class=\"text-[#666666] m-0 leading-relaxed\">Thanh toán tiền mua nguyên vật liệu, thu hồi tiền bán hàng, quản trị tín dụng thương mại và chiết khấu thanh toán.</p>\n              </div>\n              <div class=\"p-3 bg-[#FAF8F6] rounded-xl border border-[#E8E0E1] space-y-1\">\n                <strong class=\"text-[#8B1E2D]\">4. Doanh nghiệp với Chủ sở hữu (Cổ đông):</strong>\n                <p class=\"text-[#666666] m-0 leading-relaxed\">Tiếp nhận vốn góp ban đầu, vốn tăng thêm, thực hiện chi trả cổ tức bằng tiền/cổ phiếu và giải quyết mâu thuẫn đại diện (Agency Problem).</p>\n              </div>\n              <div class=\"p-3 bg-[#FAF8F6] rounded-xl border border-[#E8E0E1] space-y-1 sm:col-span-2 md:col-span-2\">\n                <strong class=\"text-[#8B1E2D]\">5. Doanh nghiệp với Người lao động:</strong>\n                <p class=\"text-[#666666] m-0 leading-relaxed\">Chi trả tiền lương, tiền công, tiền thưởng, trích nộp bảo hiểm xã hội, bảo hiểm y tế, bảo hiểm thất nghiệp và các chế độ phúc lợi tài chính nội bộ.</p>\n              </div>\n            </div>\n          </div>\n\n          <!-- Section 1.2 -->\n          <div class=\"space-y-3\">\n            <h3 class=\"text-base sm:text-lg font-extrabold text-[#8B1E2D] border-b border-[#E8E0E1] pb-1.5 flex items-center gap-2\">\n              <span>1.2.</span> Ba Quyết Định Tài Chính Then Chốt Của Doanh Nghiệp\n            </h3>\n            <p class=\"text-xs sm:text-sm text-[#333333] leading-relaxed\">\n              Mọi hoạt động của giám đốc tài chính đều xoay quanh 3 quyết định nền tảng tương ứng với 2 phần của Bảng cân đối kế toán:\n            </p>\n            <div class=\"table-container overflow-x-auto my-3\">\n              <table class=\"w-full border-collapse border border-[#E8E0E1] text-xs\">\n                <thead>\n                  <tr class=\"bg-[#8B1E2D] text-white\">\n                    <th class=\"border border-[#E8E0E1] p-2.5 text-left w-1/4\">Quyết định tài chính</th>\n                    <th class=\"border border-[#E8E0E1] p-2.5 text-left w-2/4\">Bản chất học thuật &amp; Nội dung</th>\n                    <th class=\"border border-[#E8E0E1] p-2.5 text-left w-1/4\">Liên hệ Báo cáo tài chính</th>\n                  </tr>\n                </thead>\n                <tbody class=\"divide-y divide-[#E8E0E1]\">\n                  <tr class=\"bg-white\">\n                    <td class=\"p-2.5 font-bold text-[#8B1E2D]\">1. Quyết định đầu tư (Capital Budgeting)</td>\n                    <td class=\"p-2.5 text-[#333333]\">Doanh nghiệp nên đầu tư vào những tài sản thực nào (máy móc thiết bị, nhà xưởng, mở rộng chi nhánh, R&amp;D)? Dự án nào tạo ra dòng tiền thuần có giá trị hiện tại ròng (NPV &gt; 0)?</td>\n                    <td class=\"p-2.5 text-[#666666]\">Phần Tài sản (Bên trái BCĐKT) — Tài sản cố định &amp; Dự án dài hạn.</td>\n                  </tr>\n                  <tr class=\"bg-[#FAF8F6]\">\n                    <td class=\"p-2.5 font-bold text-[#8B1E2D]\">2. Quyết định tài trợ (Capital Structure)</td>\n                    <td class=\"p-2.5 text-[#333333]\">Doanh nghiệp huy động tiền từ đâu để tài trợ cho các quyết định đầu tư? Tỷ lệ nợ vay trên vốn chủ sở hữu (D/E) bao nhiêu là tối ưu nhằm cực tiểu hóa chi phí vốn bình quân (WACC)?</td>\n                    <td class=\"p-2.5 text-[#666666]\">Phần Nguồn vốn (Bên phải BCĐKT) — Nợ phải trả &amp; Vốn chủ sở hữu.</td>\n                  </tr>\n                  <tr class=\"bg-white\">\n                    <td class=\"p-2.5 font-bold text-[#8B1E2D]\">3. Quyết định quản trị tài sản hoạt động (Working Capital Management)</td>\n                    <td class=\"p-2.5 text-[#333333]\">Quản trị tài sản ngắn hạn và nợ ngắn hạn hàng ngày như thế nào để đảm bảo tính thanh khoản, tránh nguy cơ phá sản kỹ thuật nhưng không để tiền ứ đọng lãng phí?</td>\n                    <td class=\"p-2.5 text-[#666666]\">Tài sản ngắn hạn và Nợ ngắn hạn (Vốn lưu động ròng NWC).</td>\n                  </tr>\n                </tbody>\n              </table>\n            </div>\n          </div>\n\n          <!-- Section 1.3 -->\n          <div class=\"space-y-3\">\n            <h3 class=\"text-base sm:text-lg font-extrabold text-[#8B1E2D] border-b border-[#E8E0E1] pb-1.5 flex items-center gap-2\">\n              <span>1.3.</span> Mục Tiêu Của Quản Trị Tài Chính: Lợi Nhuận vs. Giá Trị Doanh Nghiệp\n            </h3>\n            <p class=\"text-xs sm:text-sm text-[#333333] leading-relaxed\">\n              Một trong những sai lầm phổ biến nhất trong thực tế là đánh đồng mục tiêu <em>\"Tối đa hóa lợi nhuận\"</em> với mục tiêu <em>\"Tối đa hóa giá trị doanh nghiệp / tài sản của chủ sở hữu\"</em>.\n            </p>\n            <div class=\"grid grid-cols-1 sm:grid-cols-2 gap-3 my-3 text-xs\">\n              <div class=\"p-4 bg-white rounded-xl border border-red-200 space-y-2\">\n                <span class=\"inline-block px-2.5 py-1 bg-red-100 text-red-800 font-bold rounded-lg text-2xs uppercase\">Hạn chế của Tối đa hóa Lợi nhuận</span>\n                <p class=\"text-[#333333] leading-relaxed m-0\">\n                  Lợi nhuận kế toán (Net Income) là con số trên sổ sách, chịu sự chi phối của các phương pháp kế toán (khấu hao, hạch toán hàng tồn kho). Mục tiêu này có 3 nhược điểm chết người:\n                </p>\n                <ul class=\"list-disc pl-4 space-y-1 text-[#666666]\">\n                  <li><strong>Bỏ qua yếu tố thời gian:</strong> 1 tỷ VNĐ thu được hôm nay có giá trị kinh tế khác hoàn toàn 1 tỷ VNĐ thu sau 5 năm nữa.</li>\n                  <li><strong>Bỏ qua yếu tố rủi ro:</strong> Một dự án có lợi nhuận kế toán cao nhưng độ biến động rủi ro phá sản cực lớn sẽ phá hủy giá trị công ty.</li>\n                  <li><strong>Hành vi thiển cận (Short-termism):</strong> Cắt giảm chi phí bảo trì, R&amp;D để làm đẹp sổ sách ngắn hạn nhưng gây tổn hại tương lai.</li>\n                </ul>\n              </div>\n              <div class=\"p-4 bg-[#FCEEEF]/50 rounded-xl border border-[#8B1E2D]/30 space-y-2\">\n                <span class=\"inline-block px-2.5 py-1 bg-[#8B1E2D] text-white font-bold rounded-lg text-2xs uppercase\">Ưu việt của Tối đa hóa Giá trị Doanh nghiệp</span>\n                <p class=\"text-[#333333] leading-relaxed m-0\">\n                  Đối với công ty cổ phần, mục tiêu tối thượng là <strong>Tối đa hóa giá thị trường của cổ phiếu (Market Price per Share)</strong>. Mục tiêu này hoàn hảo vì:\n                </p>\n                <ul class=\"list-disc pl-4 space-y-1 text-[#333333]\">\n                  <li><strong>Phản ánh dòng tiền thực:</strong> Thị trường định giá cổ phiếu dựa trên dòng tiền tự do (FCF) thực tế mà công ty tạo ra.</li>\n                  <li><strong>Định lượng đầy đủ rủi ro:</strong> Giá cổ phiếu phản ánh tỷ suất sinh lời chiết khấu đã bao gồm phần bù rủi ro thị trường.</li>\n                  <li><strong>Tầm nhìn dài hạn bền vững:</strong> Giá trị doanh nghiệp là tổng hiện giá của toàn bộ dòng tiền tương lai vô hạn.</li>\n                </ul>\n              </div>\n            </div>\n          </div>\n\n          <!-- Chapter Summary -->\n          <div class=\"bg-[#FAF8F6] border border-[#8B1E2D]/30 rounded-2xl p-4 sm:p-5 my-4\">\n            <h4 class=\"text-xs sm:text-sm font-extrabold text-[#8B1E2D] uppercase tracking-wider mb-2 flex items-center gap-2\">\n              <span>📌</span> Tóm Tắt Trọng Tâm Chương 1\n            </h4>\n            <ul class=\"text-xs text-[#333333] space-y-1.5 pl-4 list-disc leading-relaxed\">\n              <li>Quản trị tài chính là nghệ thuật và khoa học quản trị các dòng tiền tệ nhằm tối đa hóa giá trị tài sản của cổ đông.</li>\n              <li>Ba quyết định then chốt cấu thành bảng cân đối kế toán: Quyết định đầu tư (Tài sản dài hạn), Quyết định tài trợ (Nguồn vốn nợ và vốn chủ) và Quyết định vốn lưu động (Tài sản ngắn hạn).</li>\n              <li>Mục tiêu đúng đắn của quản trị tài chính hiện đại là Tối đa hóa giá trị thị trường của doanh nghiệp, thay vì tối đa hóa lợi nhuận kế toán ngắn hạn.</li>\n              <li>Giám đốc tài chính (CFO) đóng vai trò chiến lược trong việc điều hòa dòng tiền, kiểm soát rủi ro thanh khoản và giao tiếp với thị trường vốn.</li>\n            </ul>\n          </div>\n\n          <!-- Bilingual Glossary -->\n          <div class=\"border border-[#E8E0E1] rounded-2xl p-4 bg-white\">\n            <h4 class=\"text-xs font-bold text-slate-700 uppercase tracking-wider mb-2\">Thuật Ngữ Chuyên Ngành Anh — Việt (Chương 1)</h4>\n            <div class=\"grid grid-cols-1 sm:grid-cols-2 gap-2 text-xs\">\n              <div class=\"p-2 bg-[#FAF8F6] rounded-lg\"><strong>Corporate Finance:</strong> Tài chính doanh nghiệp</div>\n              <div class=\"p-2 bg-[#FAF8F6] rounded-lg\"><strong>Capital Budgeting:</strong> Quyết định hoạch định ngân sách vốn đầu tư</div>\n              <div class=\"p-2 bg-[#FAF8F6] rounded-lg\"><strong>Capital Structure:</strong> Cơ cấu nguồn vốn (Nợ / Vốn chủ sở hữu)</div>\n              <div class=\"p-2 bg-[#FAF8F6] rounded-lg\"><strong>Working Capital:</strong> Vốn lưu động</div>\n              <div class=\"p-2 bg-[#FAF8F6] rounded-lg\"><strong>Agency Problem:</strong> Mâu thuẫn đại diện (giữa cổ đông và nhà quản lý)</div>\n              <div class=\"p-2 bg-[#FAF8F6] rounded-lg\"><strong>CFO (Chief Financial Officer):</strong> Giám đốc Tài chính</div>\n            </div>\n          </div>\n\n          <!-- Review Questions -->\n          <div class=\"bg-white border border-[#E8E0E1] rounded-2xl p-4 sm:p-5\">\n            <h4 class=\"text-xs font-bold text-[#8B1E2D] uppercase tracking-wider mb-2\">Câu Hỏi Ôn Tập Chương 1</h4>\n            <ol class=\"text-xs text-[#333333] space-y-2 pl-4 list-decimal leading-relaxed\">\n              <li>Trình bày khái niệm quản trị tài chính doanh nghiệp và phân tích 5 nhóm quan hệ tài chính cơ bản?</li>\n              <li>Phân tích mối quan hệ hữu cơ giữa 3 quyết định tài chính: Đầu tư, Tài trợ và Quản trị vốn lưu động? Quyết định nào quan trọng nhất? Vì sao?</li>\n              <li>Tại sao mục tiêu tối đa hóa giá trị doanh nghiệp lại vượt trội hơn mục tiêu tối đa hóa lợi nhuận sau thuế của kế toán? Cho ví dụ minh họa?</li>\n              <li>Thế nào là mâu thuẫn đại diện (Agency Problem) trong công ty cổ phần? Doanh nghiệp sử dụng những cơ chế nào để hạn chế chi phí đại diện?</li>\n            </ol>\n          </div>\n\n          <!-- Chapter Navigation Bar -->\n          <div class=\"flex items-center justify-between gap-2 pt-4 border-t border-[#E8E0E1] text-xs font-bold\">\n            <span class=\"text-slate-400\">← Bắt đầu giáo trình</span>\n            <a href=\"#chuong-2\" class=\"inline-flex items-center gap-1 text-[#8B1E2D] hover:text-[#C62828] bg-[#FCEEEF] px-3.5 py-2 rounded-xl transition-all\">\n              Chương 2: Phân Tích Báo Cáo Tài Chính →\n            </a>\n          </div>\n\n        </div>\n      </section>\n\n      <!-- ========================================================================= -->\n      <!-- CHƯƠNG 2: PHÂN TÍCH TÀI CHÍNH & MÔ HÌNH DUPONT                            -->\n      <!-- ========================================================================= -->\n      <section id=\"chuong-2\" class=\"bg-white rounded-xl shadow-sm border border-[#E5E7EB] p-6 sm:p-8 space-y-6\">\n\n          <!-- Chapter Header Banner -->\n          <div class=\"border-b-2 border-[#8B1E2D] pb-3 mb-6\">\n  <span class=\"text-xs font-bold text-[#8B1E2D] uppercase tracking-wider\">Chương 2 (MH21.02)</span>\n  <h2 class=\"text-2xl font-black text-[#111827] mt-1\">PHÂN TÍCH TÀI CHÍNH & MÔ HÌNH DUPONT</h2>\n  <p class=\"text-xs sm:text-sm text-gray-600 mt-1 leading-relaxed\">Hệ thống báo cáo tài chính, 5 nhóm chỉ số tài chính căn bản (Khả năng thanh toán, Hiệu quả hoạt động, Đòn bẩy nợ, Khả năng sinh lời, Giá trị thị trường) và Mô hình phân tích DuPont 3 nhân tố, 5 nhân tố.</p>\n</div>\n\n          <!-- Chapter Objectives Card -->\n          <div class=\"bg-gradient-to-br from-white via-[#FCEEEF]/40 to-[#FAF8F6] rounded-2xl border border-[#E8E0E1] p-4 sm:p-5 shadow-2xs\">\n            <div class=\"flex items-center gap-2.5 mb-3 border-b border-[#E8E0E1] pb-2.5\">\n              <span class=\"w-7 h-7 rounded-lg bg-[#8B1E2D] text-white flex items-center justify-center text-sm font-bold\">🎯</span>\n              <div>\n                <h3 class=\"font-extrabold text-[#111827] text-xs sm:text-sm m-0 tracking-tight\">Mục Tiêu Trọng Tâm Chương 2</h3>\n                <p class=\"text-[11px] text-[#666666] m-0\">Sau khi học xong chương này, người học có khả năng:</p>\n              </div>\n            </div>\n            <div class=\"grid grid-cols-1 sm:grid-cols-2 gap-3 text-xs\">\n              <div class=\"p-3 bg-white rounded-xl border border-[#E8E0E1] flex items-start gap-2.5\">\n                <span class=\"w-5 h-5 rounded-md bg-[#8B1E2D] text-white font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">1</span>\n                <div>\n                  <strong class=\"text-[#111827]\">Đọc hiểu 4 Báo cáo tài chính:</strong>\n                  <p class=\"text-[#666666] m-0 mt-0.5\">Hiểu sâu Bảng cân đối kế toán, Báo cáo kết quả hoạt động kinh doanh, Báo cáo lưu chuyển tiền tệ và Thuyết minh BCTC.</p>\n                </div>\n              </div>\n              <div class=\"p-3 bg-white rounded-xl border border-[#E8E0E1] flex items-start gap-2.5\">\n                <span class=\"w-5 h-5 rounded-md bg-[#8B1E2D] text-white font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">2</span>\n                <div>\n                  <strong class=\"text-[#111827]\">Hệ thống tỷ số tài chính:</strong>\n                  <p class=\"text-[#666666] m-0 mt-0.5\">Tính toán chính xác và diễn giải ý nghĩa kinh tế của các tỷ số thanh toán, vòng quay tài sản, cơ cấu nợ và tỷ suất sinh lời.</p>\n                </div>\n              </div>\n              <div class=\"p-3 bg-white rounded-xl border border-[#E8E0E1] flex items-start gap-2.5\">\n                <span class=\"w-5 h-5 rounded-md bg-[#8B1E2D] text-white font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">3</span>\n                <div>\n                  <strong class=\"text-[#111827]\">Mô hình phân tích DuPont:</strong>\n                  <p class=\"text-[#666666] m-0 mt-0.5\">Tách nhân tử ROE thành 3 yếu tố (Biên lợi nhuận ròng × Vòng quay tổng tài sản × Đòn bẩy tài chính) để chỉ ra điểm nghẽn kinh doanh.</p>\n                </div>\n              </div>\n              <div class=\"p-3 bg-white rounded-xl border border-[#E8E0E1] flex items-start gap-2.5\">\n                <span class=\"w-5 h-5 rounded-md bg-[#8B1E2D] text-white font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">4</span>\n                <div>\n                  <strong class=\"text-[#111827]\">Thực hành giải bài tập thực tế:</strong>\n                  <p class=\"text-[#666666] m-0 mt-0.5\">Vận dụng số liệu thực tế của doanh nghiệp để đưa ra kết luận chẩn đoán sức khỏe tài chính toàn diện.</p>\n                </div>\n              </div>\n            </div>\n          </div>\n\n          <!-- Section 2.1 -->\n          <div class=\"space-y-3\">\n            <h3 class=\"text-base sm:text-lg font-extrabold text-[#8B1E2D] border-b border-[#E8E0E1] pb-1.5 flex items-center gap-2\">\n              <span>2.1.</span> Hệ Thống Tỷ Số Tài Chính Doanh Nghiệp Chuẩn Mực\n            </h3>\n            <p class=\"text-xs sm:text-sm text-[#333333] leading-relaxed\">\n              Phân tích tỷ số tài chính (Financial Ratio Analysis) là phương pháp chuẩn hóa dữ liệu kế toán thành các chỉ số tương đối có thể so sánh được giữa các kỳ hoặc giữa các doanh nghiệp trong cùng ngành.\n            </p>\n\n            <!-- Nhóm 1: Thanh toán -->\n            <div class=\"bg-[#FAF8F6] border border-[#E8E0E1] rounded-xl p-4 space-y-2\">\n              <strong class=\"text-[#8B1E2D] font-bold block text-xs sm:text-sm\">NHÓM I: CÁC CHỈ TIÊU ĐO LƯỜNG KHẢ NĂNG THANH TOÁN (LIQUIDITY RATIOS)</strong>\n              <div class=\"grid grid-cols-1 md:grid-cols-3 gap-3 text-xs\">\n                <div class=\"p-3 bg-white rounded-lg border border-[#E8E0E1]\">\n                  <strong class=\"text-slate-900 block mb-1\">1. Tỷ số thanh toán hiện hành (CR):</strong>\n                  <div class=\"font-mono text-center text-[#8B1E2D] font-bold p-1 bg-[#FCEEEF]/50 rounded my-1\">\n                    CR = Tài sản ngắn hạn / Nợ ngắn hạn\n                  </div>\n                  <p class=\"text-[11px] text-[#666666] m-0\">Đo lường mỗi đồng nợ ngắn hạn được bảo đảm bằng bao nhiêu đồng tài sản ngắn hạn. Tiêu chuẩn thông thường: CR &ge; 1.5 - 2.0.</p>\n                </div>\n                <div class=\"p-3 bg-white rounded-lg border border-[#E8E0E1]\">\n                  <strong class=\"text-slate-900 block mb-1\">2. Tỷ số thanh toán nhanh (QR):</strong>\n                  <div class=\"font-mono text-center text-[#8B1E2D] font-bold p-1 bg-[#FCEEEF]/50 rounded my-1\">\n                    QR = (TSNH − Hàng tồn kho) / Nợ ngắn hạn\n                  </div>\n                  <p class=\"text-[11px] text-[#666666] m-0\">Loại trừ hàng tồn kho vì tính thanh khoản kém và tốn thời gian bán giải phóng. Tiêu chuẩn khuyến nghị: QR &ge; 1.0.</p>\n                </div>\n                <div class=\"p-3 bg-white rounded-lg border border-[#E8E0E1]\">\n                  <strong class=\"text-slate-900 block mb-1\">3. Tỷ số thanh toán tiền mặt (Cash Ratio):</strong>\n                  <div class=\"font-mono text-center text-[#8B1E2D] font-bold p-1 bg-[#FCEEEF]/50 rounded my-1\">\n                    Cash Ratio = (Tiền + Tương đương tiền) / Nợ ngắn hạn\n                  </div>\n                  <p class=\"text-[11px] text-[#666666] m-0\">Chỉ số khắt khe nhất, đo lường khả năng chi trả ngay lập tức bằng tiền mặt sẵn có mà không cần thu hồi công nợ.</p>\n                </div>\n              </div>\n            </div>\n\n            <!-- Nhóm 2: Hoạt động -->\n            <div class=\"bg-[#FAF8F6] border border-[#E8E0E1] rounded-xl p-4 space-y-2\">\n              <strong class=\"text-[#8B1E2D] font-bold block text-xs sm:text-sm\">NHÓM II: CÁC CHỈ TIÊU HIỆU QUẢ HOẠT ĐỘNG (ASSET MANAGEMENT RATIOS)</strong>\n              <div class=\"grid grid-cols-1 md:grid-cols-3 gap-3 text-xs\">\n                <div class=\"p-3 bg-white rounded-lg border border-[#E8E0E1]\">\n                  <strong class=\"text-slate-900 block mb-1\">1. Vòng quay hàng tồn kho (ITR):</strong>\n                  <div class=\"font-mono text-center text-[#8B1E2D] font-bold p-1 bg-[#FCEEEF]/50 rounded my-1\">\n                    ITR = Giá vốn hàng bán / Hàng tồn kho BQ\n                  </div>\n                  <p class=\"text-[11px] text-[#666666] m-0\">Số ngày luân chuyển tồn kho: <code>DSI = 365 / ITR</code>. Vòng quay càng cao chứng tỏ quản trị kho hiệu quả, ít đọng vốn.</p>\n                </div>\n                <div class=\"p-3 bg-white rounded-lg border border-[#E8E0E1]\">\n                  <strong class=\"text-slate-900 block mb-1\">2. Kỳ thu tiền bình quân (DSO):</strong>\n                  <div class=\"font-mono text-center text-[#8B1E2D] font-bold p-1 bg-[#FCEEEF]/50 rounded my-1\">\n                    DSO = (Khoản phải thu BQ &times; 365) / Doanh thu\n                  </div>\n                  <p class=\"text-[11px] text-[#666666] m-0\">Số ngày trung bình để doanh nghiệp thu hồi được tiền từ khách hàng sau khi bán chịu hàng hóa.</p>\n                </div>\n                <div class=\"p-3 bg-white rounded-lg border border-[#E8E0E1]\">\n                  <strong class=\"text-slate-900 block mb-1\">3. Vòng quay tổng tài sản (TAT):</strong>\n                  <div class=\"font-mono text-center text-[#8B1E2D] font-bold p-1 bg-[#FCEEEF]/50 rounded my-1\">\n                    TAT = Doanh thu thuần / Tổng tài sản bình quân\n                  </div>\n                  <p class=\"text-[11px] text-[#666666] m-0\">Mỗi đồng tài sản đầu tư tạo ra bao nhiêu đồng doanh thu thuần trong năm tài chính.</p>\n                </div>\n              </div>\n            </div>\n\n            <!-- Nhóm 3: Đòn bẩy nợ -->\n            <div class=\"bg-[#FAF8F6] border border-[#E8E0E1] rounded-xl p-4 space-y-2\">\n              <strong class=\"text-[#8B1E2D] font-bold block text-xs sm:text-sm\">NHÓM III: CÁC CHỈ TIÊU ĐÒN BẨY NỢ &amp; CƠ CẤU VỐN (DEBT RATIOS)</strong>\n              <div class=\"grid grid-cols-1 md:grid-cols-3 gap-3 text-xs\">\n                <div class=\"p-3 bg-white rounded-lg border border-[#E8E0E1]\">\n                  <strong class=\"text-slate-900 block mb-1\">1. Tỷ số nợ trên tổng tài sản (D/A):</strong>\n                  <div class=\"font-mono text-center text-[#8B1E2D] font-bold p-1 bg-[#FCEEEF]/50 rounded my-1\">\n                    D/A = Tổng nợ phải trả / Tổng tài sản\n                  </div>\n                  <p class=\"text-[11px] text-[#666666] m-0\">Phần trăm tài sản của công ty được tài trợ bằng nợ vay. D/A càng cao rủi ro tài chính càng lớn.</p>\n                </div>\n                <div class=\"p-3 bg-white rounded-lg border border-[#E8E0E1]\">\n                  <strong class=\"text-slate-900 block mb-1\">2. Tỷ số nợ trên vốn chủ sở hữu (D/E):</strong>\n                  <div class=\"font-mono text-center text-[#8B1E2D] font-bold p-1 bg-[#FCEEEF]/50 rounded my-1\">\n                    D/E = Tổng nợ phải trả / Vốn chủ sở hữu\n                  </div>\n                  <p class=\"text-[11px] text-[#666666] m-0\">Tỷ lệ tương quan giữa chủ nợ và cổ đông trong việc cung cấp nguồn vốn cho công ty hoạt động.</p>\n                </div>\n                <div class=\"p-3 bg-white rounded-lg border border-[#E8E0E1]\">\n                  <strong class=\"text-slate-900 block mb-1\">3. Khả năng thanh toán lãi vay (TIE):</strong>\n                  <div class=\"font-mono text-center text-[#8B1E2D] font-bold p-1 bg-[#FCEEEF]/50 rounded my-1\">\n                    TIE = EBIT / Chi phí lãi vay (I)\n                  </div>\n                  <p class=\"text-[11px] text-[#666666] m-0\">Lợi nhuận trước thuế và lãi vay (EBIT) gấp bao nhiêu lần nghĩa vụ trả lãi hàng năm. TIE &lt; 1 báo động đỏ nguy cơ vỡ nợ.</p>\n                </div>\n              </div>\n            </div>\n\n            <!-- Nhóm 4: Khả năng sinh lời -->\n            <div class=\"bg-[#FAF8F6] border border-[#E8E0E1] rounded-xl p-4 space-y-2\">\n              <strong class=\"text-[#8B1E2D] font-bold block text-xs sm:text-sm\">NHÓM IV: CÁC CHỈ TIÊU KHẢ NĂNG SINH LỜI (PROFITABILITY RATIOS)</strong>\n              <div class=\"grid grid-cols-1 md:grid-cols-3 gap-3 text-xs\">\n                <div class=\"p-3 bg-white rounded-lg border border-[#E8E0E1]\">\n                  <strong class=\"text-slate-900 block mb-1\">1. Tỷ suất sinh lời trên doanh thu (ROS):</strong>\n                  <div class=\"font-mono text-center text-[#8B1E2D] font-bold p-1 bg-[#FCEEEF]/50 rounded my-1\">\n                    ROS = Lợi nhuận sau thuế / Doanh thu thuần\n                  </div>\n                  <p class=\"text-[11px] text-[#666666] m-0\">Một đồng doanh thu thuần sau khi trừ hết chi phí và thuế thì tạo ra bao nhiêu đồng lợi nhuận ròng.</p>\n                </div>\n                <div class=\"p-3 bg-white rounded-lg border border-[#E8E0E1]\">\n                  <strong class=\"text-slate-900 block mb-1\">2. Tỷ suất sinh lời trên tổng tài sản (ROA):</strong>\n                  <div class=\"font-mono text-center text-[#8B1E2D] font-bold p-1 bg-[#FCEEEF]/50 rounded my-1\">\n                    ROA = Lợi nhuận sau thuế / Tổng tài sản bình quân\n                  </div>\n                  <p class=\"text-[11px] text-[#666666] m-0\">Đo lường năng lực sinh lời của toàn bộ tài sản được đầu tư, không phụ thuộc vào nguồn gốc nguồn vốn.</p>\n                </div>\n                <div class=\"p-3 bg-white rounded-lg border border-[#E8E0E1]\">\n                  <strong class=\"text-slate-900 block mb-1\">3. Tỷ suất sinh lời trên vốn CSH (ROE):</strong>\n                  <div class=\"font-mono text-center text-[#8B1E2D] font-bold p-1 bg-[#FCEEEF]/50 rounded my-1\">\n                    ROE = Lợi nhuận sau thuế / Vốn CSH bình quân\n                  </div>\n                  <p class=\"text-[11px] text-[#666666] m-0\">Thước đo quan trọng nhất đối với nhà đầu tư và cổ đông: mỗi đồng vốn tự có tạo ra bao nhiêu đồng lãi ròng.</p>\n                </div>\n              </div>\n            </div>\n          </div>\n\n          <!-- Section 2.2: Dupont Analysis -->\n          <div class=\"space-y-3\">\n            <h3 class=\"text-base sm:text-lg font-extrabold text-[#8B1E2D] border-b border-[#E8E0E1] pb-1.5 flex items-center gap-2\">\n              <span>2.2.</span> Mô Hình Phân Tích DuPont (DuPont Analysis)\n            </h3>\n            <p class=\"text-xs sm:text-sm text-[#333333] leading-relaxed\">\n              Mô hình DuPont do tập đoàn hóa chất DuPont sáng tạo ra là kỹ thuật tách biệt chỉ số <strong>ROE</strong> thành tích số của các nhân tố cấu thành, giúp chỉ ra chính xác nguyên nhân gốc rễ dẫn đến sự tăng giảm tỷ suất sinh lời của cổ đông.\n            </p>\n            <div class=\"bg-gradient-to-r from-[#FCEEEF] to-[#FAF8F6] p-4 sm:p-5 rounded-xl border border-[#8B1E2D]/30 my-3\">\n              <strong class=\"text-[#8B1E2D] text-sm font-extrabold block mb-2 text-center\">ĐẲNG THỨC DUPONT 3 NHÂN TỐ (3-STEP DUPONT MODEL)</strong>\n              <div class=\"p-3 bg-white rounded-xl border border-[#E8E0E1] font-mono text-center font-bold text-xs sm:text-sm text-[#8B1E2D] space-y-1\">\n                <div>ROE = (Lợi nhuận sau thuế / Doanh thu) &times; (Doanh thu / Tổng tài sản) &times; (Tổng tài sản / Vốn CSH)</div>\n                <div class=\"text-slate-700 text-xs mt-1\">ROE = Biên lợi nhuận ròng (ROS) &times; Vòng quay tổng tài sản (TAT) &times; Đòn bẩy tài chính (EM)</div>\n              </div>\n              <div class=\"grid grid-cols-1 sm:grid-cols-3 gap-3 text-xs mt-3\">\n                <div class=\"p-2.5 bg-white rounded-lg border border-[#E8E0E1] text-center\">\n                  <span class=\"font-extrabold text-[#8B1E2D] block\">1. Biên lợi nhuận ròng (ROS)</span>\n                  <p class=\"text-[11px] text-[#666666] m-0 mt-0.5\">Phản ánh <em>Hiệu quả quản trị chi phí</em> và định giá bán của doanh nghiệp.</p>\n                </div>\n                <div class=\"p-2.5 bg-white rounded-lg border border-[#E8E0E1] text-center\">\n                  <span class=\"font-extrabold text-[#8B1E2D] block\">2. Vòng quay tài sản (TAT)</span>\n                  <p class=\"text-[11px] text-[#666666] m-0 mt-0.5\">Phản ánh <em>Hiệu quả sử dụng tài sản</em> để tạo ra doanh thu bán hàng.</p>\n                </div>\n                <div class=\"p-2.5 bg-white rounded-lg border border-[#E8E0E1] text-center\">\n                  <span class=\"font-extrabold text-[#8B1E2D] block\">3. Đòn bẩy tài chính (EM)</span>\n                  <p class=\"text-[11px] text-[#666666] m-0 mt-0.5\">Phản ánh <em>Mức độ sử dụng nợ vay</em> để khuếch đại lợi nhuận vốn chủ sở hữu.</p>\n                </div>\n              </div>\n            </div>\n\n            <!-- Ví dụ minh họa tính toán Dupont -->\n            <div class=\"bg-white border-2 border-dashed border-[#8B1E2D]/40 rounded-xl p-4 my-3 space-y-2 text-xs sm:text-sm\">\n              <strong class=\"text-[#8B1E2D] font-bold block text-sm flex items-center gap-1.5\">\n                <span>🧮</span> Ví Dụ Ứng Dụng Thực Hành: Phân Tích So Sánh DuPont Giữa Công Ty A &amp; Công Ty B\n              </strong>\n              <p class=\"text-[#333333] m-0\">\n                Hai doanh nghiệp cùng hoạt động trong ngành bán lẻ có các chỉ tiêu tài chính năm 2025 như sau:\n              </p>\n              <div class=\"table-container overflow-x-auto my-2\">\n                <table class=\"w-full border-collapse border border-[#E8E0E1] text-xs\">\n                  <tr class=\"bg-[#FAF8F6]\">\n                    <th class=\"border border-[#E8E0E1] p-2 text-left\">Chỉ tiêu</th>\n                    <th class=\"border border-[#E8E0E1] p-2 text-center\">Công ty A</th>\n                    <th class=\"border border-[#E8E0E1] p-2 text-center\">Công ty B</th>\n                    <th class=\"border border-[#E8E0E1] p-2 text-left\">Nhận xét chuyên môn</th>\n                  </tr>\n                  <tr>\n                    <td class=\"p-2 border border-[#E8E0E1]\">Biên lợi nhuận ròng (ROS)</td>\n                    <td class=\"p-2 border border-[#E8E0E1] text-center font-mono font-bold text-emerald-700\">8.0%</td>\n                    <td class=\"p-2 border border-[#E8E0E1] text-center font-mono font-bold text-amber-700\">3.0%</td>\n                    <td class=\"p-2 border border-[#E8E0E1] text-[#666666]\">Công ty A kiểm soát chi phí vượt trội hơn B.</td>\n                  </tr>\n                  <tr>\n                    <td class=\"p-2 border border-[#E8E0E1]\">Vòng quay tổng tài sản (TAT)</td>\n                    <td class=\"p-2 border border-[#E8E0E1] text-center font-mono font-bold text-amber-700\">1.2 vòng</td>\n                    <td class=\"p-2 border border-[#E8E0E1] text-center font-mono font-bold text-emerald-700\">2.5 vòng</td>\n                    <td class=\"p-2 border border-[#E8E0E1] text-[#666666]\">Công ty B có tốc độ luân chuyển tài sản cao gấp đôi.</td>\n                  </tr>\n                  <tr>\n                    <td class=\"p-2 border border-[#E8E0E1]\">Đòn bẩy tài chính (EM = Tài sản / Vốn CSH)</td>\n                    <td class=\"p-2 border border-[#E8E0E1] text-center font-mono font-bold\">1.5 lần</td>\n                    <td class=\"p-2 border border-[#E8E0E1] text-center font-mono font-bold\">2.0 lần</td>\n                    <td class=\"p-2 border border-[#E8E0E1] text-[#666666]\">Công ty B sử dụng nợ vay nhiều hơn A.</td>\n                  </tr>\n                  <tr class=\"bg-[#FCEEEF]/40 font-bold\">\n                    <td class=\"p-2 border border-[#E8E0E1] text-[#8B1E2D]\">Tỷ suất sinh lời ROE = ROS &times; TAT &times; EM</td>\n                    <td class=\"p-2 border border-[#E8E0E1] text-center font-mono text-[#8B1E2D]\">14.4%</td>\n                    <td class=\"p-2 border border-[#E8E0E1] text-center font-mono text-[#8B1E2D]\">15.0%</td>\n                    <td class=\"p-2 border border-[#E8E0E1] text-[#8B1E2D]\">ROE của B cao hơn A nhưng rủi ro nợ vay cao hơn.</td>\n                  </tr>\n                </table>\n              </div>\n              <p class=\"text-[#666666] text-xs m-0 italic\">\n                <strong>Kết luận quản trị:</strong> Công ty B đạt ROE 15.0% chủ yếu nhờ chiến lược quay vòng tài sản thần tốc (2.5 vòng) và đòn bẩy nợ cao (2.0), nhưng biên lợi nhuận mỏng (3%). Công ty A có ROE 14.4% bền vững nhờ quản trị chi phí rất tốt (ROS 8%), nếu A cải thiện tốc độ bán hàng thì ROE sẽ bứt phá mạnh mẽ mà không cần gánh rủi ro nợ vay.\n              </p>\n            </div>\n          </div>\n\n          <!-- Chapter Summary -->\n          <div class=\"bg-[#FAF8F6] border border-[#8B1E2D]/30 rounded-2xl p-4 sm:p-5 my-4\">\n            <h4 class=\"text-xs sm:text-sm font-extrabold text-[#8B1E2D] uppercase tracking-wider mb-2 flex items-center gap-2\">\n              <span>📌</span> Tóm Tắt Trọng Tâm Chương 2\n            </h4>\n            <ul class=\"text-xs text-[#333333] space-y-1.5 pl-4 list-disc leading-relaxed\">\n              <li>Phân tích BCTC cung cấp cái nhìn định lượng toàn diện về thanh khoản, hiệu quả vận hành, đòn bẩy nợ và khả năng sinh lời.</li>\n              <li>Chỉ số thanh toán nhanh (QR) và hệ số thanh toán tiền mặt là tấm lá chắn quan trọng nhất phòng ngừa rủi ro phá sản ngắn hạn.</li>\n              <li>Mô hình DuPont 3 nhân tố giúp ban giám đốc bóc tách ROE thành: Quản trị chi phí (ROS) &times; Tối ưu tài sản (TAT) &times; Đòn bẩy tài chính (EM).</li>\n              <li>Khi so sánh tỷ số tài chính, bắt buộc phải đối chiếu với trung bình ngành và chuỗi thời gian nhiều năm để nhận diện xu hướng.</li>\n            </ul>\n          </div>\n\n          <!-- Bilingual Glossary -->\n          <div class=\"border border-[#E8E0E1] rounded-2xl p-4 bg-white\">\n            <h4 class=\"text-xs font-bold text-slate-700 uppercase tracking-wider mb-2\">Thuật Ngữ Chuyên Ngành Anh — Việt (Chương 2)</h4>\n            <div class=\"grid grid-cols-1 sm:grid-cols-2 gap-2 text-xs\">\n              <div class=\"p-2 bg-[#FAF8F6] rounded-lg\"><strong>Current Ratio (CR):</strong> Tỷ số thanh toán hiện hành</div>\n              <div class=\"p-2 bg-[#FAF8F6] rounded-lg\"><strong>Quick Ratio / Acid-test:</strong> Tỷ số thanh toán nhanh</div>\n              <div class=\"p-2 bg-[#FAF8F6] rounded-lg\"><strong>Days Sales Outstanding (DSO):</strong> Kỳ thu tiền bình quân</div>\n              <div class=\"p-2 bg-[#FAF8F6] rounded-lg\"><strong>Inventory Turnover Ratio:</strong> Vòng quay hàng tồn kho</div>\n              <div class=\"p-2 bg-[#FAF8F6] rounded-lg\"><strong>Return on Equity (ROE):</strong> Tỷ suất sinh lời trên vốn chủ sở hữu</div>\n              <div class=\"p-2 bg-[#FAF8F6] rounded-lg\"><strong>Equity Multiplier (EM):</strong> Đòn bẩy tài chính (Số nhân vốn chủ)</div>\n            </div>\n          </div>\n\n          <!-- Review Questions & Exercises -->\n          <div class=\"bg-white border border-[#E8E0E1] rounded-2xl p-4 sm:p-5\">\n            <h4 class=\"text-xs font-bold text-[#8B1E2D] uppercase tracking-wider mb-2\">Câu Hỏi Ôn Tập &amp; Bài Tập Vận Dụng Chương 2</h4>\n            <ol class=\"text-xs text-[#333333] space-y-2 pl-4 list-decimal leading-relaxed\">\n              <li>Tại sao khi tính tỷ số thanh toán nhanh (Quick Ratio), người ta lại loại bỏ giá trị hàng tồn kho ra khỏi tài sản ngắn hạn?</li>\n              <li>Phân tích ý nghĩa của chỉ số Số ngày thu tiền bình quân (DSO)? Nếu DSO của doanh nghiệp là 65 ngày trong khi chính sách bán chịu quy định 30 ngày thì ban giám đốc cần có hành động gì?</li>\n              <li>Doanh nghiệp X có Doanh thu thuần = 50 tỷ VNĐ, Lợi nhuận sau thuế = 5 tỷ VNĐ, Tổng tài sản bình quân = 25 tỷ VNĐ, Vốn chủ sở hữu bình quân = 10 tỷ VNĐ. Hãy áp dụng mô hình DuPont 3 nhân tố để tính ROS, TAT, EM và ROE của doanh nghiệp X?</li>\n            </ol>\n          </div>\n\n          <!-- Chapter Navigation Bar -->\n          <div class=\"flex items-center justify-between gap-2 pt-4 border-t border-[#E8E0E1] text-xs font-bold\">\n            <a href=\"#chuong-1\" class=\"inline-flex items-center gap-1 text-slate-600 hover:text-[#8B1E2D] bg-slate-100 px-3.5 py-2 rounded-xl transition-all\">\n              ← Chương 1: Tổng Quan Quản Trị Tài Chính\n            </a>\n            <a href=\"#chuong-3\" class=\"inline-flex items-center gap-1 text-[#8B1E2D] hover:text-[#C62828] bg-[#FCEEEF] px-3.5 py-2 rounded-xl transition-all\">\n              Chương 3: Hoạch Định Lợi Nhuận &amp; Đòn Bẩy →\n            </a>\n          </div>\n\n        </div>\n      </section>\n\n      <!-- ========================================================================= -->\n      <!-- CHƯƠNG 3: HOẠCH ĐỊNH LỢI NHUẬN & CÁC ĐÒN BẨY KINH DOANH                   -->\n      <!-- ========================================================================= -->\n      <section id=\"chuong-3\" class=\"bg-white rounded-xl shadow-sm border border-[#E5E7EB] p-6 sm:p-8 space-y-6\">\n\n          <!-- Chapter Header Banner -->\n          <div class=\"border-b-2 border-[#8B1E2D] pb-3 mb-6\">\n  <span class=\"text-xs font-bold text-[#8B1E2D] uppercase tracking-wider\">Chương 3 (MH21.03)</span>\n  <h2 class=\"text-2xl font-black text-[#111827] mt-1\">HOẠCH ĐỊNH LỢI NHUẬN & CÁC ĐÒN BẨY KINH DOANH</h2>\n  <p class=\"text-xs sm:text-sm text-gray-600 mt-1 leading-relaxed\">Phân tích điểm hòa vốn (BEP) kinh tế và tài chính; Bản chất, công thức và ý nghĩa của Đòn bẩy kinh doanh (DOL), Đòn bẩy tài chính (DFL) và Đòn bẩy tổng hợp (DCL).</p>\n</div>\n\n          <!-- Section 3.1: Break-even analysis -->\n          <div class=\"space-y-3\">\n            <h3 class=\"text-base sm:text-lg font-extrabold text-[#8B1E2D] border-b border-[#E8E0E1] pb-1.5 flex items-center gap-2\">\n              <span>3.1.</span> Phân Tích Điểm Hòa Vốn Kinh Tế (Break-even Analysis)\n            </h3>\n            <p class=\"text-xs sm:text-sm text-[#333333] leading-relaxed\">\n              Điểm hòa vốn là điểm mà tại đó tổng doanh thu bán hàng vừa đủ bù đắp toàn bộ tổng chi phí sản xuất kinh doanh đã bỏ ra, lợi nhuận trước lãi vay và thuế đúng bằng không (EBIT = 0).\n            </p>\n            <div class=\"grid grid-cols-1 sm:grid-cols-2 gap-3 my-3 text-xs\">\n              <div class=\"p-4 bg-[#FAF8F6] rounded-xl border border-[#E8E0E1] space-y-1.5\">\n                <strong class=\"text-[#8B1E2D] block font-bold\">1. Sản lượng hòa vốn (Q_BEP):</strong>\n                <div class=\"p-2.5 bg-white rounded-lg border border-[#E8E0E1] font-mono text-center font-bold text-[#8B1E2D]\">\n                  Q_BEP = F / (P − v)\n                </div>\n                <p class=\"text-[11px] text-[#666666] m-0\">\n                  Trong đó: <code>F</code> là tổng chi phí cố định (Định phí); <code>P</code> là đơn giá bán; <code>v</code> là chi phí biến đổi cho 1 đơn vị sản phẩm (Biến phí đơn vị); <code>(P − v)</code> là số dư đảm phí đơn vị (Contribution Margin).\n                </p>\n              </div>\n              <div class=\"p-4 bg-[#FAF8F6] rounded-xl border border-[#E8E0E1] space-y-1.5\">\n                <strong class=\"text-[#8B1E2D] block font-bold\">2. Doanh thu hòa vốn (TR_BEP):</strong>\n                <div class=\"p-2.5 bg-white rounded-lg border border-[#E8E0E1] font-mono text-center font-bold text-[#8B1E2D]\">\n                  TR_BEP = F / [ 1 − (v / P) ] = Q_BEP &times; P\n                </div>\n                <p class=\"text-[11px] text-[#666666] m-0\">\n                  Trong đó: <code>[1 − (v / P)]</code> là tỷ suất số dư đảm phí (Contribution Margin Ratio).\n                </p>\n              </div>\n            </div>\n          </div>\n\n          <!-- Section 3.2: Leverages -->\n          <div class=\"space-y-3\">\n            <h3 class=\"text-base sm:text-lg font-extrabold text-[#8B1E2D] border-b border-[#E8E0E1] pb-1.5 flex items-center gap-2\">\n              <span>3.2.</span> Đòn Bẩy Hoạt Động (DOL), Đòn Bẩy Tài Chính (DFL) &amp; Đòn Bẩy Tổng Hợp (DCL)\n            </h3>\n            <p class=\"text-xs sm:text-sm text-[#333333] leading-relaxed\">\n              Đòn bẩy trong kinh doanh là việc sử dụng các chi phí cố định (định phí hoạt động hoặc định phí tài chính) nhằm khuếch đại tỷ lệ gia tăng lợi nhuận, nhưng đồng thời cũng làm gia tăng rủi ro kinh doanh.\n            </p>\n            <div class=\"grid grid-cols-1 md:grid-cols-3 gap-3 my-3 text-xs\">\n              <div class=\"p-3.5 bg-white rounded-xl border-t-4 border-[#8B1E2D] border-x border-b border-[#E8E0E1] shadow-2xs space-y-1.5\">\n                <span class=\"px-2 py-0.5 rounded bg-[#FCEEEF] text-[#8B1E2D] font-bold text-2xs uppercase\">Đòn bẩy hoạt động</span>\n                <h4 class=\"font-bold text-slate-900 text-xs sm:text-sm\">Degree of Operating Leverage (DOL)</h4>\n                <div class=\"p-2 bg-[#FAF8F6] rounded border border-[#E8E0E1] font-mono font-bold text-center text-[#8B1E2D]\">\n                  DOL = [ Q &times; (P − v) ] / [ Q &times; (P − v) − F ]\n                </div>\n                <p class=\"text-[11px] text-[#666666] m-0 leading-relaxed\">\n                  Đo lường mức độ biến động của EBIT khi sản lượng tiêu thụ Q thay đổi 1%. Doanh nghiệp có định phí F càng lớn thì DOL càng cao.\n                </p>\n              </div>\n              <div class=\"p-3.5 bg-white rounded-xl border-t-4 border-amber-500 border-x border-b border-[#E8E0E1] shadow-2xs space-y-1.5\">\n                <span class=\"px-2 py-0.5 rounded bg-amber-50 text-amber-800 font-bold text-2xs uppercase\">Đòn bẩy tài chính</span>\n                <h4 class=\"font-bold text-slate-900 text-xs sm:text-sm\">Degree of Financial Leverage (DFL)</h4>\n                <div class=\"p-2 bg-[#FAF8F6] rounded border border-[#E8E0E1] font-mono font-bold text-center text-amber-900\">\n                  DFL = EBIT / [ EBIT − I − Dp / (1 − t) ]\n                </div>\n                <p class=\"text-[11px] text-[#666666] m-0 leading-relaxed\">\n                  Đo lường mức độ biến động của EPS khi EBIT thay đổi 1%. Xuất phát từ việc sử dụng nợ vay có chi phí lãi vay cố định (I) và cổ tức ưu đãi (Dp).\n                </p>\n              </div>\n              <div class=\"p-3.5 bg-white rounded-xl border-t-4 border-emerald-600 border-x border-b border-[#E8E0E1] shadow-2xs space-y-1.5\">\n                <span class=\"px-2 py-0.5 rounded bg-emerald-50 text-emerald-800 font-bold text-2xs uppercase\">Đòn bẩy tổng hợp</span>\n                <h4 class=\"font-bold text-slate-900 text-xs sm:text-sm\">Degree of Combined Leverage (DCL)</h4>\n                <div class=\"p-2 bg-[#FAF8F6] rounded border border-[#E8E0E1] font-mono font-bold text-center text-emerald-800\">\n                  DCL = DOL &times; DFL\n                </div>\n                <p class=\"text-[11px] text-[#666666] m-0 leading-relaxed\">\n                  Đo lường mức độ biến động của EPS khi sản lượng Q thay đổi 1%. Thể hiện rủi ro tổng hợp của toàn bộ hoạt động kinh doanh và tài chính.\n                </p>\n              </div>\n            </div>\n          </div>\n\n          <!-- Chapter Navigation Bar -->\n          <div class=\"flex items-center justify-between gap-2 pt-4 border-t border-[#E8E0E1] text-xs font-bold\">\n            <a href=\"#chuong-2\" class=\"inline-flex items-center gap-1 text-slate-600 hover:text-[#8B1E2D] bg-slate-100 px-3.5 py-2 rounded-xl transition-all\">\n              ← Chương 2: Phân Tích Báo Cáo Tài Chính\n            </a>\n            <a href=\"#chuong-4\" class=\"inline-flex items-center gap-1 text-[#8B1E2D] hover:text-[#C62828] bg-[#FCEEEF] px-3.5 py-2 rounded-xl transition-all\">\n              Chương 4: Quản Trị Vốn Lưu Động →\n            </a>\n          </div>\n\n        </div>\n      </section>\n\n      <!-- ========================================================================= -->\n      <!-- CHƯƠNG 4: QUẢN TRỊ VỐN LƯU ĐỘNG (TIỀN, PHẢI THU, TỒN KHO EOQ)             -->\n      <!-- ========================================================================= -->\n      <section id=\"chuong-4\" class=\"bg-white rounded-xl shadow-sm border border-[#E5E7EB] p-6 sm:p-8 space-y-6\">\n\n          <!-- Chapter Header Banner -->\n          <div class=\"border-b-2 border-[#8B1E2D] pb-3 mb-6\">\n  <span class=\"text-xs font-bold text-[#8B1E2D] uppercase tracking-wider\">Chương 4 (MH21.04)</span>\n  <h2 class=\"text-2xl font-black text-[#111827] mt-1\">QUẢN TRỊ VỐN LƯU ĐỘNG (TIỀN, PHẢI THU, TỒN KHO EOQ)</h2>\n  <p class=\"text-xs sm:text-sm text-gray-600 mt-1 leading-relaxed\">Chiến lược quản trị vốn lưu động thuần (NWC), quản trị ngân quỹ tiền mặt, chính sách tín dụng thương mại thu hồi nợ phải thu, và mô hình quản trị tồn kho tối ưu Wilson (EOQ).</p>\n</div>\n\n          <!-- Section 4.1: NWC & Cash Conversion Cycle -->\n          <div class=\"space-y-3\">\n            <h3 class=\"text-base sm:text-lg font-extrabold text-[#8B1E2D] border-b border-[#E8E0E1] pb-1.5 flex items-center gap-2\">\n              <span>4.1.</span> Vốn Lưu Động Ròng (NWC) &amp; Chu Kỳ Tiền Mặt (CCC)\n            </h3>\n            <div class=\"grid grid-cols-1 sm:grid-cols-2 gap-3 my-3 text-xs\">\n              <div class=\"p-4 bg-white rounded-xl border border-[#E8E0E1] space-y-1.5\">\n                <strong class=\"text-[#8B1E2D] block font-bold\">Vốn lưu động ròng (Net Working Capital - NWC):</strong>\n                <div class=\"p-2.5 bg-[#FCEEEF]/50 rounded-lg font-mono text-center font-bold text-[#8B1E2D]\">\n                  NWC = Tài sản ngắn hạn − Nợ ngắn hạn\n                </div>\n                <p class=\"text-[11px] text-[#666666] m-0\">\n                  NWC &gt; 0: Tài sản ngắn hạn được tài trợ một phần bằng nguồn vốn dài hạn an toàn; NWC &lt; 0: Dùng nợ ngắn hạn tài trợ tài sản dài hạn (chiến lược rủi ro thanh khoản cao).\n                </p>\n              </div>\n              <div class=\"p-4 bg-white rounded-xl border border-[#E8E0E1] space-y-1.5\">\n                <strong class=\"text-[#8B1E2D] block font-bold\">Chu kỳ luân chuyển tiền mặt (Cash Conversion Cycle - CCC):</strong>\n                <div class=\"p-2.5 bg-[#FCEEEF]/50 rounded-lg font-mono text-center font-bold text-[#8B1E2D]\">\n                  CCC = Số ngày tồn kho (DSI) + Số ngày thu tiền (DSO) − Số ngày trả nợ (DPO)\n                </div>\n                <p class=\"text-[11px] text-[#666666] m-0\">\n                  Khoảng thời gian từ lúc doanh nghiệp xuất tiền mặt mua nguyên vật liệu cho đến khi thu được tiền mặt từ bán sản phẩm. Rút ngắn CCC giúp giải phóng tiền mặt tự do.\n                </p>\n              </div>\n            </div>\n          </div>\n\n          <!-- Section 4.2: EOQ Model -->\n          <div class=\"space-y-3\">\n            <h3 class=\"text-base sm:text-lg font-extrabold text-[#8B1E2D] border-b border-[#E8E0E1] pb-1.5 flex items-center gap-2\">\n              <span>4.2.</span> Mô Hình Đặt Hàng Kinh Tế Tối Ưu (Economic Order Quantity - EOQ)\n            </h3>\n            <p class=\"text-xs sm:text-sm text-[#333333] leading-relaxed\">\n              Mô hình EOQ tìm quy mô đặt hàng tối ưu sao cho tổng chi phí lưu kho (Holding cost) và chi phí đặt hàng (Ordering cost) là nhỏ nhất.\n            </p>\n            <div class=\"bg-gradient-to-r from-[#FCEEEF] to-[#FAF8F6] p-4 sm:p-5 rounded-xl border border-[#8B1E2D]/30 my-3 space-y-2\">\n              <strong class=\"text-[#8B1E2D] text-sm font-extrabold block text-center\">CÔNG THỨC MÔ HÌNH EOQ CHUẨN MỰC</strong>\n              <div class=\"p-3 bg-white rounded-xl border border-[#E8E0E1] font-mono text-center font-bold text-sm text-[#8B1E2D]\">\n                EOQ = √ [ (2 &times; D &times; S) / H ]\n              </div>\n              <div class=\"text-xs text-[#333333] space-y-1\">\n                <div>• <code>D</code>: Nhu cầu sử dụng nguyên vật liệu / sản phẩm hàng năm (đơn vị: sản phẩm).</div>\n                <div>• <code>S</code>: Chi phí cho mỗi lần đặt hàng (đơn vị: VNĐ/lần đặt).</div>\n                <div>• <code>H</code>: Chi phí lưu kho cho 1 đơn vị hàng tồn kho trong 1 năm (đơn vị: VNĐ/sản phẩm/năm).</div>\n                <div>• Tổng chi phí tồn kho hàng năm: <code>TC = (D / Q) &times; S + (Q / 2) &times; H</code></div>\n                <div>• Điểm đặt hàng lại (Reorder Point): <code>ROP = d &times; L</code> (với <code>d</code> là nhu cầu tiêu dùng mỗi ngày, <code>L</code> là thời gian chờ hàng về - Lead time).</div>\n              </div>\n            </div>\n          </div>\n\n          <!-- Chapter Navigation Bar -->\n          <div class=\"flex items-center justify-between gap-2 pt-4 border-t border-[#E8E0E1] text-xs font-bold\">\n            <a href=\"#chuong-3\" class=\"inline-flex items-center gap-1 text-slate-600 hover:text-[#8B1E2D] bg-slate-100 px-3.5 py-2 rounded-xl transition-all\">\n              ← Chương 3: Hoạch Định Lợi Nhuận\n            </a>\n            <a href=\"#chuong-5\" class=\"inline-flex items-center gap-1 text-[#8B1E2D] hover:text-[#C62828] bg-[#FCEEEF] px-3.5 py-2 rounded-xl transition-all\">\n              Chương 5: Các Nguồn Tài Trợ Doanh Nghiệp →\n            </a>\n          </div>\n\n        </div>\n      </section>\n\n      <!-- ========================================================================= -->\n      <!-- CHƯƠNG 5: CÁC NGUỒN TÀI TRỢ CỦA DOANH NGHIỆP                              -->\n      <!-- ========================================================================= -->\n      <section id=\"chuong-5\" class=\"bg-white rounded-xl shadow-sm border border-[#E5E7EB] p-6 sm:p-8 space-y-6\">\n\n          <!-- Chapter Header Banner -->\n          <div class=\"border-b-2 border-[#8B1E2D] pb-3 mb-6\">\n  <span class=\"text-xs font-bold text-[#8B1E2D] uppercase tracking-wider\">Chương 5 (MH21.05)</span>\n  <h2 class=\"text-2xl font-black text-[#111827] mt-1\">CÁC NGUỒN TÀI TRỢ CỦA DOANH NGHIỆP</h2>\n  <p class=\"text-xs sm:text-sm text-gray-600 mt-1 leading-relaxed\">Phân loại tài trợ ngắn hạn, trung hạn và dài hạn; Nguồn vốn nợ (Tín dụng thương mại, Vay ngân hàng, Phát hành trái phiếu) và Vốn chủ sở hữu (Lợi nhuận giữ lại, Phát hành cổ phiếu thường và ưu đãi).</p>\n</div>\n\n          <!-- Chi phí tín dụng thương mại -->\n          <div class=\"space-y-3\">\n            <h3 class=\"text-base sm:text-lg font-extrabold text-[#8B1E2D] border-b border-[#E8E0E1] pb-1.5 flex items-center gap-2\">\n              <span>5.1.</span> Chi Phí Thực Tế Khi Bỏ Qua Chiết Khấu Tín Dụng Thương Mại\n            </h3>\n            <p class=\"text-xs sm:text-sm text-[#333333] leading-relaxed\">\n              Khi nhà cung cấp đưa ra điều khoản thanh toán dạng <code>[d% / t_d net t_n]</code> (ví dụ: <code>2/10 net 30</code>: chiết khấu 2% nếu trả trong 10 ngày, nếu không phải trả đủ toàn bộ trong 30 ngày):\n            </p>\n            <div class=\"bg-[#FAF8F6] border border-[#E8E0E1] rounded-xl p-4 space-y-2 text-xs sm:text-sm\">\n              <strong class=\"text-[#8B1E2D] font-bold block text-sm\">CÔNG THỨC CHI PHÍ DANH NGHĨA (APR) &amp; CHI PHÍ THỰC TẾ (EAR):</strong>\n              <div class=\"p-3 bg-white rounded-lg border border-[#E8E0E1] font-mono text-center font-bold text-[#8B1E2D]\">\n                APR = [ %CK / (100% − %CK) ] &times; [ 365 / (Thời hạn tín dụng − Thời hạn hưởng CK) ]\n              </div>\n              <div class=\"p-3 bg-white rounded-lg border border-[#E8E0E1] font-mono text-center font-bold text-amber-900\">\n                EAR = [ 1 + %CK / (100% − %CK) ] ^ [ 365 / (t_n − t_d) ] − 1\n              </div>\n              <p class=\"text-xs text-[#666666] m-0\">\n                <em>Ví dụ với điều khoản 2/10 net 30:</em> <code>APR = [2% / 98%] &times; [365 / (30 − 10)] = 2.04% &times; 18.25 = 37.24%/năm</code>. Một chi phí vốn vay ngắn hạn khổng lồ (37.24%), do đó doanh nghiệp nên vay ngân hàng (lãi suất thường chỉ 8 - 12%/năm) để thanh toán sớm và nhận chiết khấu!\n              </p>\n            </div>\n          </div>\n\n          <!-- Chapter Navigation Bar -->\n          <div class=\"flex items-center justify-between gap-2 pt-4 border-t border-[#E8E0E1] text-xs font-bold\">\n            <a href=\"#chuong-4\" class=\"inline-flex items-center gap-1 text-slate-600 hover:text-[#8B1E2D] bg-slate-100 px-3.5 py-2 rounded-xl transition-all\">\n              ← Chương 4: Quản Trị Vốn Lưu Động\n            </a>\n            <a href=\"#chuong-6\" class=\"inline-flex items-center gap-1 text-[#8B1E2D] hover:text-[#C62828] bg-[#FCEEEF] px-3.5 py-2 rounded-xl transition-all\">\n              Chương 6: Giá Trị Tiền Tệ Theo Thời Gian →\n            </a>\n          </div>\n\n        </div>\n      </section>\n\n      <!-- ========================================================================= -->\n      <!-- CHƯƠNG 6: GIÁ TRỊ TIỀN TỆ THEO THỜI GIAN (TVM)                            -->\n      <!-- ========================================================================= -->\n      <section id=\"chuong-6\" class=\"bg-white rounded-xl shadow-sm border border-[#E5E7EB] p-6 sm:p-8 space-y-6\">\n\n          <!-- Chapter Header Banner -->\n          <div class=\"border-b-2 border-[#8B1E2D] pb-3 mb-6\">\n  <span class=\"text-xs font-bold text-[#8B1E2D] uppercase tracking-wider\">Chương 6 (MH21.06)</span>\n  <h2 class=\"text-2xl font-black text-[#111827] mt-1\">GIÁ TRỊ TIỀN TỆ THEO THỜI GIAN & THẨM ĐỊNH ĐẦU TƯ</h2>\n  <p class=\"text-xs sm:text-sm text-gray-600 mt-1 leading-relaxed\">Nguyên lý giá trị thời gian của tiền (TVM): Giá trị tương lai (FV), Giá trị hiện tại (PV), Dòng tiền đều (Annuity); Các tiêu chuẩn thẩm định dự án đầu tư vốn: PP, NPV, IRR, PI.</p>\n</div>\n\n          <!-- TVM Formulas Matrix -->\n          <div class=\"space-y-3\">\n            <h3 class=\"text-base sm:text-lg font-extrabold text-[#8B1E2D] border-b border-[#E8E0E1] pb-1.5 flex items-center gap-2\">\n              <span>6.1.</span> Bộ Công Thức Giá Trị Thời Gian Của Tiền Kinh Điển\n            </h3>\n            <div class=\"grid grid-cols-1 sm:grid-cols-2 gap-3 my-3 text-xs\">\n              <div class=\"p-3.5 bg-white rounded-xl border border-[#E8E0E1] space-y-1\">\n                <strong class=\"text-[#8B1E2D] block\">1. Giá trị tương lai khoản tiền đơn (FV):</strong>\n                <div class=\"p-2 bg-[#FAF8F6] rounded font-mono font-bold text-center text-[#8B1E2D]\">\n                  FV_n = PV &times; (1 + r)^n\n                </div>\n                <p class=\"text-[11px] text-[#666666] m-0\">Với kỳ ghép lãi m lần trong năm: <code>FV_n = PV &times; (1 + r/m)^(n&times;m)</code></p>\n              </div>\n              <div class=\"p-3.5 bg-white rounded-xl border border-[#E8E0E1] space-y-1\">\n                <strong class=\"text-[#8B1E2D] block\">2. Giá trị hiện tại khoản tiền đơn (PV):</strong>\n                <div class=\"p-2 bg-[#FAF8F6] rounded font-mono font-bold text-center text-[#8B1E2D]\">\n                  PV = FV_n / (1 + r)^n = FV_n &times; (1 + r)^(-n)\n                </div>\n                <p class=\"text-[11px] text-[#666666] m-0\">Số tiền ở hiện tại cần đầu tư với lãi suất r để đạt FV_n sau n kỳ.</p>\n              </div>\n              <div class=\"p-3.5 bg-white rounded-xl border border-[#E8E0E1] space-y-1\">\n                <strong class=\"text-[#8B1E2D] block\">3. Giá trị hiện tại niên kim thường (PVA):</strong>\n                <div class=\"p-2 bg-[#FAF8F6] rounded font-mono font-bold text-center text-[#8B1E2D]\">\n                  PVA = A &times; [ (1 − (1 + r)^(-n)) / r ]\n                </div>\n                <p class=\"text-[11px] text-[#666666] m-0\">Dòng tiền đều A phát sinh vào cuối mỗi kỳ trong n kỳ liên tiếp.</p>\n              </div>\n              <div class=\"p-3.5 bg-white rounded-xl border border-[#E8E0E1] space-y-1\">\n                <strong class=\"text-[#8B1E2D] block\">4. Giá trị tương lai niên kim thường (FVA):</strong>\n                <div class=\"p-2 bg-[#FAF8F6] rounded font-mono font-bold text-center text-[#8B1E2D]\">\n                  FVA = A &times; [ ((1 + r)^n − 1) / r ]\n                </div>\n                <p class=\"text-[11px] text-[#666666] m-0\">Tổng số tiền tích lũy được ở cuối kỳ n từ việc gửi góp đều đặn A cuối mỗi kỳ.</p>\n              </div>\n              <div class=\"p-3.5 bg-white rounded-xl border border-[#E8E0E1] space-y-1\">\n                <strong class=\"text-[#8B1E2D] block\">5. Dòng tiền vĩnh viễn (Perpetuity):</strong>\n                <div class=\"p-2 bg-[#FAF8F6] rounded font-mono font-bold text-center text-[#8B1E2D]\">\n                  PV_vô_hạn = A / r\n                </div>\n                <p class=\"text-[11px] text-[#666666] m-0\">Dòng tiền đều A kéo dài mãi mãi (áp dụng định giá cổ phiếu ưu đãi hoặc trái phiếu vĩnh viễn).</p>\n              </div>\n              <div class=\"p-3.5 bg-white rounded-xl border border-[#E8E0E1] space-y-1\">\n                <strong class=\"text-[#8B1E2D] block\">6. Lãi suất hiệu dụng thực tế hàng năm (EAR):</strong>\n                <div class=\"p-2 bg-[#FAF8F6] rounded font-mono font-bold text-center text-[#8B1E2D]\">\n                  EAR = (1 + r_nom / m)^m − 1\n                </div>\n                <p class=\"text-[11px] text-[#666666] m-0\">Lãi suất thực tế nhận được khi ghép lãi m lần trong năm với lãi danh nghĩa r_nom.</p>\n              </div>\n            </div>\n          </div>\n\n          <!-- Chapter Navigation Bar -->\n          <div class=\"flex items-center justify-between gap-2 pt-4 border-t border-[#E8E0E1] text-xs font-bold\">\n            <a href=\"#chuong-5\" class=\"inline-flex items-center gap-1 text-slate-600 hover:text-[#8B1E2D] bg-slate-100 px-3.5 py-2 rounded-xl transition-all\">\n              ← Chương 5: Các Nguồn Tài Trợ Doanh Nghiệp\n            </a>\n            <a href=\"#chuong-7\" class=\"inline-flex items-center gap-1 text-[#8B1E2D] hover:text-[#C62828] bg-[#FCEEEF] px-3.5 py-2 rounded-xl transition-all\">\n              Chương 7: Định Giá Chứng Khoán &amp; WACC →\n            </a>\n          </div>\n\n        </div>\n      </section>\n\n      <!-- ========================================================================= -->\n      <!-- CHƯƠNG 7: ĐỊNH GIÁ CHỨNG KHOÁN & CHI PHÍ SỬ DỤNG VỐN (WACC)              -->\n      <!-- ========================================================================= -->\n      <section id=\"chuong-7\" class=\"bg-white rounded-xl shadow-sm border border-[#E5E7EB] p-6 sm:p-8 space-y-6\">\n\n          <!-- Chapter Header Banner -->\n          <div class=\"border-b-2 border-[#8B1E2D] pb-3 mb-6\">\n  <span class=\"text-xs font-bold text-[#8B1E2D] uppercase tracking-wider\">Chương 7 (MH21.07)</span>\n  <h2 class=\"text-2xl font-black text-[#111827] mt-1\">ĐỊNH GIÁ CHỨNG KHOÁN & CHI PHÍ SỬ DỤNG VỐN (WACC)</h2>\n  <p class=\"text-xs sm:text-sm text-gray-600 mt-1 leading-relaxed\">Mô hình định giá trái phiếu, mô hình chiết khấu cổ tức Gordon định giá cổ phiếu; Chi phí sử dụng vốn nợ sau thuế, chi phí vốn chủ sở hữu (CAPM) và Chi phí sử dụng vốn bình quân gia quyền (WACC).</p>\n</div>\n\n          <!-- Section 7.1: WACC Formula -->\n          <div class=\"space-y-3\">\n            <h3 class=\"text-base sm:text-lg font-extrabold text-[#8B1E2D] border-b border-[#E8E0E1] pb-1.5 flex items-center gap-2\">\n              <span>7.1.</span> Chi Phí Vốn Bình Quân (Weighted Average Cost of Capital - WACC)\n            </h3>\n            <p class=\"text-xs sm:text-sm text-[#333333] leading-relaxed\">\n              WACC là tỷ suất sinh lời tối thiểu mà doanh nghiệp phải tạo ra trên các khoản đầu tư của mình để làm thỏa mãn các nhà cung cấp vốn (chủ nợ và cổ đông).\n            </p>\n            <div class=\"bg-gradient-to-r from-[#FCEEEF] to-[#FAF8F6] p-4 sm:p-5 rounded-xl border border-[#8B1E2D]/30 my-3 space-y-2\">\n              <strong class=\"text-[#8B1E2D] text-sm font-extrabold block text-center\">CÔNG THỨC WACC CHUẨN MỰC TÀI CHÍNH DOANH NGHIỆP</strong>\n              <div class=\"p-3 bg-white rounded-xl border border-[#E8E0E1] font-mono text-center font-bold text-sm text-[#8B1E2D]\">\n                WACC = w_d &times; r_d &times; (1 − t) + w_p &times; r_p + w_e &times; r_e\n              </div>\n              <div class=\"grid grid-cols-1 sm:grid-cols-3 gap-2.5 text-xs mt-2\">\n                <div class=\"p-2.5 bg-white rounded-lg border border-[#E8E0E1]\">\n                  <strong class=\"text-slate-900 block mb-0.5\">1. Chi phí nợ sau thuế:</strong>\n                  <code>r_d &times; (1 − t)</code>\n                  <p class=\"text-[11px] text-[#666666] m-0 mt-0.5\">Lãi vay được trừ vào thu nhập chịu thuế nên tạo ra lá chắn thuế (Tax Shield).</p>\n                </div>\n                <div class=\"p-2.5 bg-white rounded-lg border border-[#E8E0E1]\">\n                  <strong class=\"text-slate-900 block mb-0.5\">2. Chi phí cổ phiếu ưu đãi:</strong>\n                  <code>r_p = D_p / P_net</code>\n                  <p class=\"text-[11px] text-[#666666] m-0 mt-0.5\">Cổ tức ưu đãi D_p chia cho giá phát hành ròng sau khi trừ chi phí phát hành.</p>\n                </div>\n                <div class=\"p-2.5 bg-white rounded-lg border border-[#E8E0E1]\">\n                  <strong class=\"text-slate-900 block mb-0.5\">3. Chi phí vốn cổ phần (CAPM):</strong>\n                  <code>r_e = R_f + &beta; &times; (R_m − R_f)</code>\n                  <p class=\"text-[11px] text-[#666666] m-0 mt-0.5\">Tỷ suất phi rủi ro cộng với phần bù rủi ro thị trường nhân với hệ số Beta.</p>\n                </div>\n              </div>\n            </div>\n          </div>\n\n          <!-- Chapter Navigation Bar -->\n          <div class=\"flex items-center justify-between gap-2 pt-4 border-t border-[#E8E0E1] text-xs font-bold\">\n            <a href=\"#chuong-6\" class=\"inline-flex items-center gap-1 text-slate-600 hover:text-[#8B1E2D] bg-slate-100 px-3.5 py-2 rounded-xl transition-all\">\n              ← Chương 6: Giá Trị Tiền Tệ Theo Thời Gian\n            </a>\n            <a href=\"#chuong-8\" class=\"inline-flex items-center gap-1 text-[#8B1E2D] hover:text-[#C62828] bg-[#FCEEEF] px-3.5 py-2 rounded-xl transition-all\">\n              Chương 8: Cơ Cấu Vốn &amp; Điểm Bàng Quan →\n            </a>\n          </div>\n\n        </div>\n      </section>\n\n      <!-- ========================================================================= -->\n      <!-- CHƯƠNG 8: CƠ CẤU VỐN & PHÂN TÍCH ĐIỂM BÀNG QUAN EBIT-EPS                  -->\n      <!-- ========================================================================= -->\n      <section id=\"chuong-8\" class=\"bg-white rounded-xl shadow-sm border border-[#E5E7EB] p-6 sm:p-8 space-y-6\">\n\n          <!-- Chapter Header Banner -->\n          <div class=\"border-b-2 border-[#8B1E2D] pb-3 mb-6\">\n  <span class=\"text-xs font-bold text-[#8B1E2D] uppercase tracking-wider\">Chương 8 (MH21.08)</span>\n  <h2 class=\"text-2xl font-black text-[#111827] mt-1\">CƠ CẤU VỐN & PHÂN TÍCH ĐIỂM BÀNG QUAN EBIT-EPS</h2>\n  <p class=\"text-xs sm:text-sm text-gray-600 mt-1 leading-relaxed\">Lý thuyết cơ cấu vốn Modigliani-Miller (MM) trong điều kiện có thuế và không thuế; Lý thuyết đánh đổi Trade-off; Phương pháp phân tích điểm bàng quan EBIT-EPS lựa chọn phương án tài trợ tối ưu.</p>\n</div>\n\n          <!-- Section 8.1: EBIT-EPS Indifference Point -->\n          <div class=\"space-y-3\">\n            <h3 class=\"text-base sm:text-lg font-extrabold text-[#8B1E2D] border-b border-[#E8E0E1] pb-1.5 flex items-center gap-2\">\n              <span>8.1.</span> Phân Tích Điểm Bàng Quan EBIT-EPS\n            </h3>\n            <p class=\"text-xs sm:text-sm text-[#333333] leading-relaxed\">\n              Điểm bàng quan EBIT-EPS là mức lợi nhuận trước lãi vay và thuế (EBIT) mà tại đó thu nhập trên một cổ phần (EPS) của hai phương án tài trợ khác nhau (ví dụ: phát hành cổ phiếu thường vs. vay nợ ngân hàng) là hoàn toàn như nhau.\n            </p>\n            <div class=\"bg-[#FAF8F6] border border-[#E8E0E1] rounded-xl p-4 space-y-2 text-xs sm:text-sm\">\n              <strong class=\"text-[#8B1E2D] font-bold block text-sm\">PHƯƠNG TRÌNH XÁC ĐỊNH ĐIỂM BÀNG QUAN EBIT-EPS:</strong>\n              <div class=\"p-3 bg-white rounded-lg border border-[#E8E0E1] font-mono text-center font-bold text-[#8B1E2D]\">\n                [ (EBIT* − I₁) &times; (1 − t) − Dp₁ ] / S₁ = [ (EBIT* − I₂) &times; (1 − t) − Dp₂ ] / S₂\n              </div>\n              <ul class=\"text-xs text-[#333333] pl-4 list-disc space-y-1\">\n                <li><code>EBIT*</code>: Mức lợi nhuận trước thuế và lãi vay tại điểm bàng quan.</li>\n                <li><code>I₁, I₂</code>: Chi phí lãi vay hàng năm của phương án 1 và phương án 2.</li>\n                <li><code>S₁, S₂</code>: Số lượng cổ phiếu thường đang lưu hành của phương án 1 và phương án 2.</li>\n                <li><strong>Quy tắc quyết định:</strong> Nếu EBIT kỳ vọng của doanh nghiệp &gt; EBIT* &rarr; Chọn phương án sử dụng đòn bẩy nợ (vay nợ) để tối đa hóa EPS; Nếu EBIT kỳ vọng &lt; EBIT* &rarr; Chọn phương án phát hành cổ phiếu thường để bảo đảm an toàn tài chính.</li>\n              </ul>\n            </div>\n          </div>\n\n          <!-- Tài liệu tham khảo toàn tập -->\n          <div class=\"bg-white border border-[#E8E0E1] rounded-2xl p-5 my-4\">\n            <h4 class=\"text-xs sm:text-sm font-extrabold text-[#8B1E2D] uppercase tracking-wider mb-3 flex items-center gap-2\">\n              <span>📚</span> Danh Mục Tài Liệu Tham Khảo Giáo Trình Quản Trị Tài Chính\n            </h4>\n            <ol class=\"text-xs text-[#333333] space-y-1.5 pl-4 list-decimal leading-relaxed\">\n              <li>Trường Cao đẳng Kinh tế TP.HCM (2021), <em>Giáo trình Quản trị tài chính (MH21)</em>, Lưu hành nội bộ.</li>\n              <li>PGS.TS. Trần Ngọc Thơ (2020), <em>Tài chính doanh nghiệp hiện đại</em>, NXB Kinh tế TP. Hồ Chí Minh.</li>\n              <li>Brigham, E. F., &amp; Ehrhardt, M. C. (2020), <em>Financial Management: Theory &amp; Practice</em>, 16th Edition, Cengage Learning.</li>\n              <li>Ross, S. A., Westerfield, R. W., &amp; Jaffe, J. (2019), <em>Corporate Finance</em>, 12th Edition, McGraw-Hill Education.</li>\n              <li>Quốc hội nước CHXHCN Việt Nam, <em>Luật Doanh nghiệp số 59/2020/QH14</em> và <em>Luật Chứng khoán số 54/2019/QH14</em>.</li>\n            </ol>\n          </div>\n\n          <!-- Footer Back to Top -->\n          <div class=\"flex items-center justify-between gap-2 pt-4 border-t border-[#E8E0E1] text-xs font-bold\">\n            <a href=\"#chuong-7\" class=\"inline-flex items-center gap-1 text-slate-600 hover:text-[#8B1E2D] bg-slate-100 px-3.5 py-2 rounded-xl transition-all\">\n              ← Chương 7: Định Giá Chứng Khoán &amp; WACC\n            </a>\n            <a href=\"#chuong-1\" class=\"inline-flex items-center gap-1 text-[#8B1E2D] hover:text-[#C62828] bg-[#FCEEEF] px-3.5 py-2 rounded-xl transition-all\">\n              ↑ Về Đầu Trang\n            </a>\n          </div>\n\n        </div>\n      </section>\n\n    </div>\n  </div>\n  ";
